// String-level repairs for the math/symbol corruption in catalog_book_chunks.
//
// The corpus was generated by an LLM and a chunk of its output lost the `\` and
// `$` characters, which came through as raw control bytes instead - plus some
// terminal ANSI colour codes that were captured verbatim. Every reconstruction
// here is validated by re-rendering through KaTeX; if the rebuilt math does not
// parse we fall back to simply deleting the junk, which is never worse than the
// status quo (control characters do not render at all).

import katex from 'katex';
import 'katex/contrib/mhchem';
import { normalizeText, tokenize, relaxed } from './site-render.mjs';

// DEL belongs with the rest: the generator used it in the same places — either
// side of `\ce{Cu^{2+}}`, straight after the `{` of a `\text{` — so it is one
// more byte a lost `\` or `$` came through as, not a character of the text.
const C = '\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F';
// …but only as far as restoring a `\` and clearing the byte away. Inferring a
// *delimiter* from it is a step too far: DEL also turns up simply glued to a
// numeral — `␡10 followed by ␡10 gives ␡10^2` — and pairing those off sets two
// words of the sentence as an equation. The bytes below are the ones that only
// ever stood in for a delimiter.
const D = '\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F';
const HAS_CTRL = new RegExp(`[${C}]`);
const CTRL_RUN = new RegExp(`[${C}]+`, 'g');
const PAIR_RUN = new RegExp(`[${D}]+`, 'g');

// Commands that stand alone, so wrapping just the command in $...$ is safe.
const SYMBOLS =
  'ldots|cdots|dots|perp|parallel|angle|triangle|times|div|circ|infty|pi|theta|alpha|beta|gamma|lambda|mu|omega|Delta|Omega|approx|neq|leq|geq|pm|mp|rightarrow|Rightarrow|leftarrow|to|bullet|degree|prime';

export function mathOk(tex, displayMode = false) {
  try {
    katex.renderToString(tex, { displayMode, throwOnError: true, strict: false });
    return true;
  } catch {
    return false;
  }
}

/** A whole string that is nothing but a URL, a media path or a data URI. */
const URL_ONLY = /^\s*(?:https?:\/\/|\/\/|\/|data:|\.\/)\S*\s*$/;

// The site's own normaliser turns a literal `\n` into a real newline before it
// renders — but only when no letter follows, so `\neq` survives. Storing the
// newline therefore changes nothing for the reader, while stopping the command
// wrapper from reading `\ce{...}\n\nHere, ...` as one unbroken run.
const LITERAL_NEWLINE = /(?<!\\)\\n(?![A-Za-z])/g;

// Every command KaTeX knows that starts with `n`, read straight off the bundle,
// plus the document-level ones the generator occasionally emits. A `\n` glued to
// a word is only a newline when the whole letter run is *not* one of these.
const N_COMMANDS = new Set(
  ('nLeftarrow nLeftrightarrow nRightarrow nVDash nVdash nabla natnums natural ncong ne nearrow ' +
    'neg negmedspace negthickspace negthinspace neq newcommand newline nexists ngeq ngeqq ' +
    'ngeqslant ngtr ni nleftarrow nleftrightarrow nleq nleqq nleqslant nless nmid nobreak ' +
    'nobreakspace noexpand nolimits nonumber normalsize not notag notin notni nparallel nprec ' +
    'npreceq nrightarrow nshortmid nshortparallel nsim nsubseteq nsubseteqq nsucc nsucceq ' +
    'nsupseteq nsupseteqq ntriangleleft ntrianglelefteq ntriangleright ntrianglerighteq nu ' +
    'nvDash nvdash nwarrow newenvironment newpage nicefrac noindent normalfont numberwithin'
  ).split(' '),
);

const GLUED_NEWLINE = /(?<!\\)\\n([A-Za-z]+)/g;

export function decodeLiteralNewlines(s) {
  if (!s.includes('\\n')) return s;
  const t = s.replace(LITERAL_NEWLINE, '\n');
  if (!t.includes('\\n')) return t;
  // What survives is a `\n` glued to a word. Inside maths that is a command and
  // has to stay; outside it, `\nHence` is the paragraph break the generator
  // wrote as a C escape — decode it unless the letter run names a real command.
  const spans = mathSpans(t);
  return t.replace(GLUED_NEWLINE, (whole, word, i) =>
    inSpan(spans, i) || N_COMMANDS.has(`n${word}`) ? whole : `\n${word}`,
  );
}

// The deployed Worker rewrites a literal `\n` to a real newline before it
// tokenizes, and the guard it makes an exception for is far shorter than the set
// of commands that start with `n`: only \nu, \ne, \neq, \neg, \not, \notin,
// \nabla and \newline, and only when a word boundary follows. So `$a\ne0$`
// reaches the reader as "a" newline "e0", and `\nmid` never renders at all.
// The renderer is not ours to change, so the content has to be written in a form
// its guard already accepts. Sticky, so it can be asked about one position.
const SITE_NEWLINE = /\\n(?!u(?:\b|_)|e(?:q|g)?\b|ot(?:in)?\b|abla\b|ewline\b)/y;

// The eight the Worker will leave alone; for these a single space is enough,
// since what breaks them is a digit or letter sitting where the boundary goes.
const SITE_KEEPS = new Set(['nu', 'ne', 'neq', 'neg', 'not', 'notin', 'nabla', 'newline']);

// For the rest, an equivalent KaTeX renders the same way and that does not open
// with `\n`. `\not\mid` is ∤ exactly as `\nmid` is; the arrows have no negated
// form, so they become the character itself.
const N_REWRITE = new Map([
  ['nmid', '\\not\\mid'],
  ['nsubseteq', '\\not\\subseteq'],
  ['nsupseteq', '\\not\\supseteq'],
  ['nleq', '\\not\\leq'],
  ['ngeq', '\\not\\geq'],
  ['nexists', '\\not\\exists'],
  ['nparallel', '\\not\\parallel'],
  ['nRightarrow', '\\not\\Rightarrow'],
  ['nLeftarrow', '\\not\\Leftarrow'],
  ['nrightarrow', '\\not\\rightarrow'],
  ['nleftarrow', '\\not\\leftarrow'],
  ['ncong', '\\not\\cong'],
  ['nsim', '\\not\\sim'],
  ['nless', '\\not<'],
  ['ngtr', '\\not>'],
  ['nprec', '\\not\\prec'],
  ['nsucc', '\\not\\succ'],
  ['nvdash', '\\not\\vdash'],
  ['nvDash', '\\not\\vDash'],
  ['ntriangleleft', '\\not\\triangleleft'],
  ['ntriangleright', '\\not\\triangleright'],
  ['ni', '\\owns'],
  ['nearrow', '↗'],
  ['nwarrow', '↖'],
  ['natural', '♮'],
]);

export function protectNCommands(s) {
  if (!s.includes('\\n')) return s;
  let out = '';
  let cursor = 0;
  for (const m of s.matchAll(/\\n([A-Za-z]+)/g)) {
    if (m.index < cursor) continue;
    const name = `n${m[1]}`;
    // Anything that is not exactly a command is prose, and the newline the
    // Worker puts there is the right reading of it.
    if (!N_COMMANDS.has(name)) continue;
    SITE_NEWLINE.lastIndex = m.index;
    if (!SITE_NEWLINE.test(s)) continue; // the guard already covers it
    const fixed = SITE_KEEPS.has(name) ? `\\${name} ` : N_REWRITE.get(name);
    if (!fixed) continue;
    out += s.slice(cursor, m.index) + fixed;
    cursor = m.index + m[0].length;
  }
  return cursor ? out + s.slice(cursor) : s;
}

// The four entities that survived the scrape. None of them is `&amp;`, `&lt;`
// or `&gt;`, so decoding cannot introduce markup or an alignment tab.
const NBSP = String.fromCharCode(0x00a0);
const EMSP = String.fromCharCode(0x2003);
const ENTITIES = new Map([
  ['&emsp;', EMSP],
  ['&nbsp;', NBSP],
  ['&quot;', '"'],
  ['&epsis;', 'ε'],
]);
const ENTITY_RE = /&(?:emsp|nbsp|quot|epsis);/g;

export function decodeEntities(s) {
  return s.includes('&') ? s.replace(ENTITY_RE, (e) => ENTITIES.get(e)) : s;
}

/** Index ranges covered by $...$ or $$...$$ so we never edit inside live math. */
// `multiline` matches the site tokenizer, which scans on past a newline looking
// for the closing `$`. The passes that only ever *add* delimiters ask for it, so
// they cannot hand a second pair to a `$\boxed{\begin{aligned}…` that already
// renders. The rest keep the tighter rule: a pass that rewrites what it finds
// inside a span must not have a stray `$` hand it half a paragraph.
function mathSpans(s, multiline = false) {
  const spans = [];
  const re = multiline
    ? /\$\$[\s\S]*?\$\$|(?<!\\)\$[^$]*?(?<!\\)\$/g
    : /\$\$[\s\S]*?\$\$|(?<!\\)\$[^$\n]*?(?<!\\)\$/g;
  let m;
  while ((m = re.exec(s)) !== null) spans.push([m.index, m.index + m[0].length]);
  return spans;
}
const inSpan = (spans, i) => spans.some(([a, b]) => i >= a && i < b);

/** The `{` that the `}` at `close` matches, or -1. */
function matchOpenBrace(s, close) {
  let depth = 0;
  for (let i = close; i >= 0; i--) {
    if (i > 0 && s[i - 1] === '\\') {
      i -= 1;
      continue;
    }
    if (s[i] === '}') depth++;
    else if (s[i] === '{' && --depth === 0) return i;
  }
  return -1;
}

function matchBrace(s, open) {
  let depth = 0;
  for (let i = open; i < s.length; i++) {
    if (s[i] === '\\') { i++; continue; }
    if (s[i] === '{') depth++;
    else if (s[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

// A shortcode marker that lost the ESC byte the ANSI pass keys on, or lost its
// opening bracket outright (`[tex]\vec r[/tex]` -> `tex]\vec rtex]`). They stood
// for `$`, but the span they framed still carries its own delimiters wherever
// they survive, so dropping the marker is what leaves the reader a clean line.
const ORPHAN_SHORTCODE = /(?<![A-Za-z])(?:\[\/?(?:la|ka)?tex\]|\[\/?(?:math|chem)\]|(?:la|ka)?tex\])+/gi;

export function stripShortcodeMarkers(s) {
  if (!/tex\]|math\]|chem\]/i.test(s)) return s;
  return s.replace(ORPHAN_SHORTCODE, '');
}

// ---------------------------------------------------------------- ANSI codes

export function repairAnsi(s) {
  // Not only ESC: the same markers turn up behind FS and RS too.
  if (!HAS_CTRL.test(s)) return s;
  // ESC[1m ... ESC[0m was bold emphasis; the content model speaks markdown.
  s = s.replace(/\[[13]m([\s\S]*?)\[0m/g, (_, inner) =>
    inner.trim() ? `**${inner}**` : inner,
  );
  // A handful of rows encode chemistry as ESC[chem]{...}.
  s = s.replace(/\[chem\]\{([^{}]*)\}/g, (_, x) =>
    mathOk(`\\ce{${x}}`) ? `$\\ce{${x}}$` : x,
  );
  // Shortcode delimiters — [latex]...[/latex], [KaTeX]...[/KaTeX] — whose
  // leading `\` the escape handling ate. Both halves mean the same thing: `$`.
  // The brackets are missing about as often as not, and the byte in front is
  // not always ESC, so the name is what identifies one; a letter after it means
  // this is `\mathrm` with its backslash eaten, not a marker.
  const marker = `[${C}]+\\[?/?(?:latex|katex|math|tex|inline|display|block)(?:\\]|(?![A-Za-z]))`;
  // One `$` each, kept apart. Markers running together are either one delimiter
  // the generator wrote twice — `␛[KaTeX]␛[Inline]n=6␛[KaTeX]␛[Inline]` — or an
  // opener and a closer whose content the corruption ate — `through ␛KaTeX␛
  // [KaTeX] and`. Nothing here can tell those apart, so both are handed on as
  // empty spans for dropEmptySpans to settle.
  // Written as a sentinel first, so the parity check below can tell a delimiter
  // this pass invented from one the source already had. U+E000 is private use:
  // no book text carries it, but bail out rather than corrupt one that does.
  const MARK = '\uE000';
  let markers = 0;
  if (!s.includes(MARK))
    s = s.replace(new RegExp(`(?:${marker})+`, 'gi'), (run, at, whole) => {
      // A marker up against a delimiter that survived is saying the same thing
      // twice — `␜KaTeX␞$2\sqrt3$␜KaTeX␞`. Another `$` there would open a span the
      // real one then closes, and the equation would fall out of both.
      const near = new RegExp(`[${C}\\s]*$`);
      const before = whole.slice(0, at).replace(near, '').slice(-1);
      const after = whole.slice(at + run.length).replace(new RegExp(`^[${C}\\s]*`), '')[0];
      if (before === '$' || after === '$') return '';
      const n = (run.match(new RegExp(marker, 'gi')) || []).length;
      markers += n;
      return `${MARK} `.repeat(n).trim();
    });
  // A single marker whose partner the corruption ate — `␛[KaTeX]\boxed{x=1}).` —
  // would open a span nothing closes. The wrapping passes downstream then read
  // the command after it as bare source and give it a pair of its own, and the
  // reader is left with `$ $\boxed{x=1}$)$`: an empty formula box followed by the
  // formula as text. Our own spare is the delimiter to give up, since the
  // command it stood in front of is exactly what those passes know how to wrap.
  // Only when the source's own delimiters are already even, or the odd one out
  // is the author's and dropping ours would misalign every pair after it.
  if (markers === 1 && (s.match(/(?<!\\)\$/g) || []).length % 2 === 0)
    s = s.replace(MARK, '');
  s = s.split(MARK).join('$');
  // Codes wedged between two spans must leave a gap behind, or `$a$` and `$b$`
  // fuse into `$a$$b$`, and `$$` reads as display math.
  s = s.replace(new RegExp('(?<=\\$)(?:\\u001b\\[[0-9;?]*m|\\u001b\\[?)+(?=\\$)', 'g'), ' ');
  // Remaining well-formed SGR codes are pure terminal noise.
  s = s.replace(/\[[0-9;?]*m/g, '');
  // Truncated fragments such as ESC[ before real content: drop the marker only,
  // never the character after it (that is usually a chemical symbol).
  s = s.replace(/\[?/g, '');
  return s;
}

// ------------------------------------------------------- chemistry (\ce{...})

// The control byte swallowed `\`, or `\c`, sometimes with stray junk alongside.
const CE_START = new RegExp(`[${C}][${C}\\\\A-Za-z0-9]{0,6}?(c?e)\\{`, 'g');

export function repairChem(s) {
  if (!HAS_CTRL.test(s)) return s;
  const spans = mathSpans(s);
  let out = '';
  let last = 0;
  let m;
  CE_START.lastIndex = 0;
  while ((m = CE_START.exec(s)) !== null) {
    if (inSpan(spans, m.index)) continue;
    const open = m.index + m[0].length - 1;
    const close = matchBrace(s, open);
    if (close === -1) continue;
    let body = s.slice(open + 1, close);
    // mhchem tolerates `\ce{$S_{N1}$}`, but wrapping it would nest delimiters
    // and break every `$`-based parser downstream. Drop the inner ones.
    if (body.includes('$')) body = body.replace(/\$/g, '');
    if (!mathOk(`\\ce{${body}}`)) continue;
    out += s.slice(last, m.index) + `$\\ce{${body}}$`;
    last = close + 1;
    CE_START.lastIndex = last;
  }
  return out + s.slice(last);
}

// ------------------------------------------- control bytes standing in for $

// KaTeX will happily typeset a Marathi sentence, so "it parses" is not enough
// to prove a fragment was ever math. These books are bilingual and their prose
// is Indic or plain English; an expression is neither.
const INDIC = /[ऀ-෿]/;
const TEXT_ARG = /\\text(?:rm|bf|it|normal|sf|tt)?\{[^{}]*\}/g;

function looksLikeMath(inner) {
  const t = inner.trim();
  if (!t || t.includes('\n')) return false;
  // Any script is fine inside \text{...}; nowhere else.
  const bare = t.replace(TEXT_ARG, '');
  if (INDIC.test(bare)) return false;
  // Two ordinary words in a row is a sentence. Command names do not count:
  // they are always preceded by a backslash.
  if (/(?:^|[^\\A-Za-z])[A-Za-z]{3,}\s+[A-Za-z]{3,}/.test(bare)) return false;
  // And it has to contain something mathematical at all.
  return /[\\^_=+<>0-9]/.test(bare) || /^[A-Za-z]$/.test(bare);
}

/**
 * Treat the surviving control runs as `$` and pair them off left to right.
 *
 * A rejected candidate hands its closing run back to the scan instead of
 * consuming it: a sentence sitting between two expressions must not throw every
 * later pair out of phase, or `$a$ text $b$` comes back as `a $text$ b`.
 */
function pairControlRuns(s) {
  const runs = [...s.matchAll(PAIR_RUN)].map((m) => [m.index, m.index + m[0].length]);
  if (runs.length < 2) return s;
  let out = '';
  let cursor = 0;
  for (let i = 0; i < runs.length - 1; ) {
    const [open, afterOpen] = runs[i];
    const inner = s.slice(afterOpen, runs[i + 1][0]);
    if (inner.length > 160 || !looksLikeMath(inner) || !mathOk(inner.trim())) {
      i++;
      continue;
    }
    out += s.slice(cursor, open) + `$${inner.trim()}$`;
    cursor = runs[i + 1][1];
    i += 2;
  }
  return out + s.slice(cursor);
}

export function repairDelimiters(s) {
  if (!HAS_CTRL.test(s)) return s;
  // A pair of control runs around a LaTeX expression used to be $ ... $.
  s = s.replace(
    new RegExp(`[${D}]+(\\\\[A-Za-z]+[^${C}$]*?)[${D}]+`, 'g'),
    (whole, inner) =>
      looksLikeMath(inner) && mathOk(inner.trim()) ? `$${inner.trim()}$` : whole,
  );
  // The same pairing where the expression opens with a variable rather than a
  // command: `FS a=4, FS` was `$a=4,$`, and dropping the bytes would silently
  // demote real math to prose.
  s = pairControlRuns(s);
  // Junk sitting between two spans must leave a gap behind: deleting it would
  // fuse `$a$` and `$b$` into `$a$$b$`, and `$$` means display math.
  s = s.replace(new RegExp(`(?<=\\$)[${C}]+(?=\\$)`, 'g'), ' ');
  // Control junk hugging a real delimiter is just litter.
  s = s.replace(new RegExp(`[${C}]+(?=\\$)`, 'g'), '');
  s = s.replace(new RegExp(`(?<=\\$)[${C}]+`, 'g'), '');
  return s;
}

// ------------------------------------------------ control bytes eating a `\`

// Commands that are meaningless without a `{...}` argument, so seeing one bare
// in front of a brace is proof its backslash went missing rather than evidence
// of a variable named `frac`.
const ARG_CMDS =
  'operatorname|underline|overline|textrm|textbf|textit|mathrm|mathbf|mathrm|dfrac|tfrac|binom|sqrt|frac|text|boxed|begin|end|vec|hat|bar';

export function repairCommands(s) {
  if (!HAS_CTRL.test(s)) return s;
  const spans = mathSpans(s);
  // Inside math the backslash is all that is missing.
  s = s.replace(new RegExp(`[${C}]+([A-Za-z]+)`, 'g'), (whole, word, idx) => {
    if (!inSpan(spans, idx)) return whole;
    return mathOk(`\\${word}`) || /^(frac|dfrac|sqrt|text|textrm|mathrm|overline|vec|hat)$/.test(word)
      ? `\\${word}`
      : whole;
  });
  // Outside math, a standalone symbol command needs delimiters too.
  s = s.replace(new RegExp(`[${C}]+\\\\?(${SYMBOLS})\\b`, 'g'), (whole, cmd) =>
    mathOk(`\\${cmd}`) ? `$\\${cmd}$` : whole,
  );
  // Outside math too: a control byte in front of a command that always takes an
  // argument can only ever have been that command's backslash.
  s = s.replace(new RegExp(`[${C}]+(${ARG_CMDS})(?=\\{)`, 'g'), (_, w) => `\\${w}`);
  return s;
}

// ------------------------------- tab / CR that ate the backslash of a command

// The generator interpreted C escapes, so `\textrm` arrived as TAB+"extrm" and
// `\rightarrow` as CR+"ightarrow". LF is deliberately excluded: real newlines
// are everywhere in this content and `$$\nu^2` is a genuine line break plus the
// variable u, not a corrupted `\nu`.
const ESCAPED = [
  ['t', '\\u0009', 'extrm|extbf|extit|extdiv|exttimes|extdegree|extminus|ext|riangle|imes|heta|ilde|frac|au|an|o'],
  ['r', '\\u000D', 'ightleftharpoons|ightarrow|ight|ho|m'],
  ['f', '\\u000C', 'rac|orall|lat'],
  ['v', '\\u000B', 'arepsilon|arnothing|arphi|ert|ec'],
  ['b', '\\u0008', 'egin|igcup|igcap|igl|igr|igg|ig|inom|oxed|ullet|ar|eta|mod'],
  ['a', '\\u0007', 'lpha|ngle|pprox|rray|ligned|lign|rrow|st|leph'],
];
// Only when what follows still looks like LaTeX, never mid-word in prose. A
// control byte counts: it is a delimiter that has not been rebuilt yet.
const TAIL_GUARD = `(?=[{\\\\^_$(\\[${C}]|\\s|$)`;

export function repairEscapedCommands(s) {
  if (!HAS_CTRL.test(s) && !/[\t\r]/.test(s)) return s;
  for (const [letter, code, tails] of ESCAPED) {
    s = s.replace(new RegExp(`${code}(${tails})${TAIL_GUARD}`, 'g'), (_, t) => `\\${letter}${t}`);
  }
  return s;
}

// ------------------------------------------------ literal escapes / aliases

// A few rows carry the *text* `` where their neighbours carry the byte:
// one JSON round-trip too few. Decode them so the control-byte repairs above
// see a single, consistent representation.
const LITERAL_CTRL = /\\u00([01][0-9A-Fa-f])/g;

export function decodeLiteralEscapes(s) {
  if (!s.includes('\\u00')) return s;
  return s.replace(LITERAL_CTRL, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
}

// Commands the generator invented. KaTeX rejects them, and a reader just sees
// the source, so map them onto the real thing.
const ALIASES = [
  [/\\textdiv/g, '\\div'],
  [/\\texttimes/g, '\\times'],
  [/\\textdegree/g, '^\\circ'],
  [/\\textminus/g, '-'],
  [/\\centernot/g, '\\not'],
];

export function normalizeAliases(s) {
  if (!/\\(?:text(?:div|times|degree|minus)|centernot)/.test(s)) return s;
  let t = s;
  for (const [re, to] of ALIASES) t = t.replace(re, to);
  return t;
}

// ------------------------------------------------- over-escaped delimiters

// Some rows carry `\$\ce{K+}\$`: the generator escaped its own math delimiters,
// so the browser shows a literal `$` and the LaTeX as raw source. Only unescape
// when the enclosed text really is a LaTeX command, never for prices like `\$5`.
export function normalizeEscapedDollars(s) {
  if (!s.includes('\\$')) return s;
  const t = s.replace(/\\\$([^$]*?\\[A-Za-z]+[^$]*?)\\\$/g, (whole, inner) =>
    mathOk(inner) ? `$${inner}$` : whole,
  );
  // Often only the opener was escaped — `\$\ce{BF3}$` — which leaves the closer
  // to pair with whatever `$` comes next and drags the prose between them into
  // maths. Same guard: the span has to hold a command and has to render.
  return t.replace(/\\\$([^$]*?\\[A-Za-z]+[^$]*?)\$/g, (whole, inner) =>
    mathOk(inner) ? `$${inner}$` : whole,
  );
}

// ------------------------------------------ LaTeX stranded outside math mode

// A bare `\command` in prose renders as literal source, so it is always a bug.
// Wrap the maximal LaTeX-looking run in $...$ when KaTeX accepts it.
//
// The run scanner must balance braces: `\boxed{\text{a}\text{b}}` is ONE
// expression, and matching its inner fragments separately would shred it.
function scanRun(s, start) {
  let i = start;
  for (;;) {
    if (s[i] === '\\' && /[A-Za-z]/.test(s[i + 1] || '')) {
      i += 2;
      while (i < s.length && /[A-Za-z]/.test(s[i])) i++;
      continue;
    }
    if (s[i] === '{') {
      const c = matchBrace(s, i);
      if (c === -1) break;
      i = c + 1;
      continue;
    }
    if (s[i] === '^' || s[i] === '_') {
      i++;
      if (s[i] === '{') {
        const c = matchBrace(s, i);
        if (c === -1) break;
        i = c + 1;
      } else i++;
      continue;
    }
    break;
  }
  return i;
}

/**
 * Brace depth *before* each position, escapes skipped. Anything the wrappers
 * below find at depth > 0 is already an argument of an enclosing command —
 * `\begin{aligned}` inside `\boxed{…}` — and putting a `$` around it would move
 * the group's content outside its own braces. The span regex cannot rule that
 * out on its own, because the enclosing `$` is often the unbalanced one.
 */
function braceDepths(s) {
  const depth = new Array(s.length + 1).fill(0);
  for (let i = 0, d = 0; i < s.length; i++) {
    if (s[i] === '\\') depth[++i] = d;
    else if (s[i] === '{') d++;
    else if (s[i] === '}') d = Math.max(0, d - 1);
    depth[i + 1] = d;
  }
  return depth;
}

// What can open a real LaTeX group: a command, a script, or the brace of an
// argument that has just closed. Anything else — `R = {(x, y): …}`, `{2, 3, 5}`
// — is a sentence's own brace, set notation the reader typed, and an expression
// inside it is at the top level as far as a span is concerned.
const ATTACHED_BRACE = /(?:[_^{}]|\\[A-Za-z]+\s*(?:\[[^\]]*\]\s*)?)$/;

/** Like `braceDepths`, but counting only the braces LaTeX itself opened. */
function groupDepths(s) {
  const depth = new Array(s.length + 1).fill(0);
  const real = [];
  for (let i = 0, d = 0; i < s.length; i++) {
    if (s[i] === '\\') depth[++i] = d;
    else if (s[i] === '{') {
      const attached = ATTACHED_BRACE.test(s.slice(Math.max(0, i - 24), i));
      real.push(attached);
      if (attached) d++;
    } else if (s[i] === '}') {
      if (real.pop() !== false) d = Math.max(0, d - 1);
    }
    depth[i + 1] = d;
  }
  return depth;
}

/**
 * A grid the generator left outside every `$...$` span. The renderer hands it
 * to nothing, so the reader sees `\begin{array}{c|c}...` as literal source.
 * Wrapping it as display maths is what the rest of the corpus does, and it puts
 * the grid where the table conversion can find it.
 */
export function wrapBareArrays(s) {
  if (!s.includes('\\begin{array}')) return s;
  const spans = mathSpans(s);
  const re = /(\\boxed\{)?\\begin\{array\}[\s\S]*?\\end\{array\}/g;
  const depth = braceDepths(s);
  let out = '';
  let cursor = 0;
  for (const m of s.matchAll(re)) {
    if (inSpan(spans, m.index) || m.index < cursor || depth[m.index] !== 0) continue;
    let end = m.index + m[0].length;
    let tex = m[0];
    if (m[1]) {
      // Only claim the wrapper when it closes right here; otherwise the `}`
      // belongs to something else and moving it would break that instead.
      if (s[end] !== '}') continue;
      end += 1;
      tex += '}';
    }
    if (!mathOk(tex, true)) continue;
    // The generator often wrote the grid inside *single* delimiters. Inline
    // maths cannot cross a newline, so the tokenizer never pairs them and the
    // reader is shown the source: the pair is right and only the delimiter is
    // wrong. Promote it in place — adding a second pair around it would leave
    // `$$$…$$$`, a display span framed by two loose dollars.
    let from = m.index;
    const lone = (i) => s[i] === '$' && s[i - 1] !== '$' && s[i - 1] !== '\\' && s[i + 1] !== '$';
    if (lone(from - 1) && lone(end)) {
      from -= 1;
      end += 1;
    }
    out += s.slice(cursor, from) + `$$${tex}$$`;
    cursor = end;
  }
  return cursor ? out + s.slice(cursor) : s;
}

const FENCE_OPEN = /\\left(?![A-Za-z])/g;
// `\right` takes a delimiter, and the delimiter may itself be a command: `\|`,
// `\rangle`, or the `.` that means "no bracket on this side".
const FENCE_STEP = /\\(left|right)(?![A-Za-z])[ \t]*(\\[A-Za-z]+|\\.|[^\s])?/g;

/** End index just past the `\right…` closing the `\left` at `i`, or -1. */
function matchFence(s, i) {
  FENCE_STEP.lastIndex = i;
  let depth = 0;
  let m;
  while ((m = FENCE_STEP.exec(s)) !== null) {
    if (!m[2]) return -1; // a fence with no delimiter: the source is broken
    if (m[1] === 'left') depth++;
    else if (--depth === 0) return m.index + m[0].length;
    else if (depth < 0) return -1;
  }
  return -1;
}

/**
 * `the point of contact is \left(\dfrac{a}{m^2},\, \dfrac{2a}{m}\right).` — a
 * whole fenced expression sitting in a sentence with no delimiters around it.
 * The run scanner stops at the comma and the command wrapper takes one fraction
 * at a time, so each bracket is left outside the span it was there to size and
 * the reader is shown `\left(` as source.
 *
 * This runs *after* those wrappers, not before: a `\left` they could reach is
 * better claimed as part of the run around it — pre-empting them turns
 * `\sin\left(-\frac{\pi}{3}\right)=…` into two spans with `\sin` alone in the
 * first. What is left here is a pair they could not put back together, and a
 * `\left…\right` pair is unambiguous: it cannot occur outside maths at all.
 */
export function wrapBareFences(s) {
  if (!/\\left(?![A-Za-z])/.test(s)) return s;
  const spans = mathSpans(s);
  const depth = groupDepths(s);
  let out = '';
  let cursor = 0;
  for (const m of s.matchAll(FENCE_OPEN)) {
    if (m.index < cursor || inSpan(spans, m.index) || depth[m.index] !== 0) continue;
    const end = matchFence(s, m.index);
    if (end < 0 || depth[end] !== 0) continue;
    const raw = s.slice(m.index, end);
    // Inline maths cannot cross a line, and a pair that spans one is far more
    // likely to be two broken halves than one expression. A display delimiter
    // inside the pair means a whole block is in there; that is not a bracket
    // the sentence lost, and merging across it would move the block.
    if (raw.includes('\n') || raw.includes('$$')) continue;
    // The pieces the wrappers did claim are part of this expression too. Take
    // them back rather than leave the brackets outside the maths they size —
    // but only if their delimiters pair up, so nothing outside is disturbed.
    const inner = (raw.match(/(?<!\\)\$/g) || []).length;
    if (inner % 2) continue;
    const tex = raw.replace(/(?<!\\)\$/g, '');
    if (!mathOk(tex)) continue;
    out += s.slice(cursor, m.index) + `$${tex}$`;
    cursor = end;
  }
  return cursor ? out + s.slice(cursor) : s;
}

/**
 * The same damage for every other environment — `A = \begin{bmatrix}1 & 2\\3 &
 * 4\end{bmatrix} and B = ...`. The run scanner cannot reach these because `&`
 * and `\\` end a run, so they need claiming whole. `array` is left to the pass
 * above, which sets it as display so the table conversion can find it.
 */
const BARE_ENV = /\\begin\{([A-Za-z]+\*?)\}[\s\S]*?\\end\{\1\}/g;

export function wrapBareEnvironments(s) {
  if (!s.includes('\\begin{')) return s;
  const spans = mathSpans(s);
  const depth = braceDepths(s);
  let out = '';
  let cursor = 0;
  for (const m of s.matchAll(BARE_ENV)) {
    if (m[1] === 'array' || inSpan(spans, m.index) || m.index < cursor) continue;
    if (depth[m.index] !== 0) continue;
    // Alone on its line it was meant to be a display block; sitting in a
    // sentence — `A = ... and B = ...` — it has to stay inline.
    const head = s.lastIndexOf('\n', m.index) + 1;
    const tailAt = m.index + m[0].length;
    const nl = s.indexOf('\n', tailAt);
    const alone =
      !s.slice(head, m.index).trim() && !s.slice(tailAt, nl === -1 ? s.length : nl).trim();
    const d = alone ? '$$' : '$';
    if (!mathOk(m[0], alone)) continue;
    out += s.slice(cursor, m.index) + `${d}${m[0]}${d}`;
    cursor = tailAt;
  }
  return cursor ? out + s.slice(cursor) : s;
}

/**
 * `\vec $r_{1}$` — the generator opened the span one command too late, so the
 * reader gets a literal `\vec` and an italic r. The command belongs inside.
 */
const LEADING_CMD = /(?<!\\)\\([A-Za-z]+)[ \t]*(?<!\\)\$(?!\$)([^$\n]+?)(?<!\\)\$/g;

export function absorbLeadingCommand(s) {
  if (!s.includes('$')) return s;
  const spans = mathSpans(s);
  return s.replace(LEADING_CMD, (whole, name, body, i) => {
    // The command has to be *outside* the span it precedes, and the merged
    // span has to render — `\vec` with nothing to accent would not.
    if (inSpan(spans, i)) return whole;
    const merged = `\\${name} ${body}`;
    return mathOk(merged) && !mathOk(`\\${name}`) ? `$${merged}$` : whole;
  });
}

// Page-layout commands. KaTeX has no use for them outside maths and the reader
// just sees the source, so they go rather than get wrapped.
const LAYOUT_CMD = /(?<!\\)\\(?:hfill|noindent|newpage|clearpage|par)(?![A-Za-z])[ \t]*/g;

export function dropLayoutCommands(s) {
  if (!/\\(?:hfill|noindent|newpage|clearpage|par)/.test(s)) return s;
  const spans = mathSpans(s);
  return s.replace(LAYOUT_CMD, (whole, i) => (inSpan(spans, i) ? whole : ''));
}

// `\multicolumn{4}{l}{(Being 100 equity shares…)}` in a ledger row. It is a
// `tabular` command: KaTeX has none, and outside a `\begin{tabular}` there are
// no columns for it to span either. The cell wants what is inside it.
const MULTICOLUMN = /\\multicolumn\s*\{\s*\d+\s*\}\s*\{[^{}]*\}\s*\{/g;

export function dropMulticolumn(s) {
  if (!s.includes('\\multicolumn')) return s;
  const spans = mathSpans(s, true);
  let out = '';
  let cursor = 0;
  let m;
  MULTICOLUMN.lastIndex = 0;
  while ((m = MULTICOLUMN.exec(s)) !== null) {
    if (inSpan(spans, m.index)) continue;
    const open = m.index + m[0].length - 1;
    const close = matchBrace(s, open);
    if (close < 0) continue;
    out += s.slice(cursor, m.index) + s.slice(open + 1, close);
    cursor = close + 1;
    MULTICOLUMN.lastIndex = cursor;
  }
  return cursor ? out + s.slice(cursor) : s;
}

/**
 * `\\ce{H2SO4}` sitting in a sentence: the generator doubled its own escape.
 * Outside maths a `\\` is a Markdown hard break and is always followed by the
 * end of the line, so one glued to a command name is a backslash too many —
 * and left alone the wrapper below starts the span *after* it, printing the
 * stray `\$` as a literal dollar in the middle of the sentence.
 */
export function undoubleCommands(s) {
  if (!s.includes('\\\\')) return s;
  const spans = mathSpans(s);
  // An environment left outside every span still uses `\\` as a row break, and
  // `\\\text{...}` is a row followed by a cell, not a doubled escape. Halving it
  // would collapse the grid into one row, so those regions are off limits too.
  if (s.includes('\\begin{')) {
    for (const m of s.matchAll(BARE_ENV)) spans.push([m.index, m.index + m[0].length]);
  }
  return s.replace(/\\\\(?=[A-Za-z])/g, (whole, i) => (inSpan(spans, i) ? whole : '\\'));
}

// ------------------------------------------------- ASCIIMath left in the prose
//
// Source pages that used MathJax's AsciiMath input left `CO_(2)`, `x^(2)` and
// `S_{10}` sitting in ordinary sentences. KaTeX never sees them, so the reader
// gets the source: "concentration of CO_(2) in stomata".

// Enough of the periodic table to recognise a formula. Two or more of these,
// accounting for every letter in the token, means chemistry — which is set
// upright — as against a maths variable, which is italic.
const ELEMENTS = new Set(
  ('H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se ' +
    'Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pt Au Hg Tl Pb Bi Po ' +
    'At Rn Fr Ra Ac Th Pa U Np Pu').split(' '),
);

// Cyrillic look-alikes ride in with this notation: `ХО_(2)` is XO₂ typed on a
// Russian layout and `О_(3)` is ozone, not a Cyrillic O. Nothing in an Indian
// board syllabus is written in Cyrillic, so inside a token we are already
// reading as maths the substitution is unambiguous.
const HOMOGLYPHS = new Map(
  Object.entries({
    А: 'A', В: 'B', С: 'C', Е: 'E', Н: 'H', К: 'K', М: 'M', О: 'O', Р: 'P', Т: 'T', Х: 'X', У: 'Y',
    а: 'a', е: 'e', о: 'o', р: 'p', с: 'c', х: 'x', у: 'y',
  }),
);
const deHomoglyph = (s) => s.replace(/[Ѐ-ӿ]/gu, (c) => HOMOGLYPHS.get(c) ?? c);

/**
 * A sub/superscript argument, or null when it is not safe to interpret.
 *
 * `hasBase` is what separates a prefix script from a fill-in-the-blank. With a
 * base, `n_(air)` and `∆_(r)H` are ordinary physics. Without one, the only
 * honest readings are a short index — `^(12)C`, `^(n)C_(3)` — and anything
 * longer is the English workbook's `_____________(deliver)`.
 */
function scriptArg(raw, hasBase = true) {
  const a = deHomoglyph(raw).trim().replace(/[−–—]/g, '-');
  if (!a) return null;
  if (/^(?:th|st|nd|rd)$/i.test(a)) return `\\text{${a}}`;
  if (!hasBase && !/^(?:[0-9]{1,3}|[A-Za-z])$/.test(a)) return null;
  // Digits, signs, short index expressions: 2, -1, 2+, n, ij, n-1, 2n.
  if (/^[A-Za-z0-9+\-,]{1,8}$/.test(a)) return a;
  if (a === '°' || a === '∘') return '\\circ';
  if (/^[Α-ω]$/u.test(a)) return a; // Θ in ∆_(f)H^(Θ)
  return null;
}

// Letters a base may be written in. Greek is meant (`λ^(2)`, `∆_(r)H`);
// Cyrillic is not, but it is here, and deHomoglyph puts it right.
const BASE_CHAR = /[A-Za-z0-9Α-ωЀ-ӿ∆]/u;

/**
 * Split `C_(2)H_(5)OH`, `Ca(OH)_(2)`, `*x*^(2)` or `(m + 1)^(th)` into its
 * base/script segments, or null if malformed. A part with no `op` is the tail
 * of the token — the `OH` of `C_(2)H_(5)OH` — and a part with an empty `base`
 * is a prefix script, as in `^(12)C`.
 */
function parseScriptToken(tok) {
  const parts = [];
  let i = 0;
  const readBase = () => {
    let base = '';
    while (i < tok.length) {
      if (tok[i] === '*') { i += 1; continue; } // markdown emphasis around a variable
      if (tok[i] === '(') {
        // Balanced, so a base can hold a script of its own: `(x^(2) + 2x)`.
        let depth = 0;
        let j = i;
        for (; j < tok.length; j++) {
          if (tok[j] === '(') depth += 1;
          else if (tok[j] === ')' && --depth === 0) break;
        }
        if (j >= tok.length) break;
        base += tok.slice(i, j + 1);
        i = j + 1;
        continue;
      }
      if (!BASE_CHAR.test(tok[i])) break;
      base += tok[i++];
    }
    return base;
  };
  while (i < tok.length) {
    const base = readBase();
    if (i >= tok.length) {
      if (base) parts.push({ base });
      break;
    }
    const op = tok[i++];
    if (op !== '_' && op !== '^') return null;
    let arg;
    if (tok[i] === '(' || tok[i] === '{') {
      const close = tok.indexOf(tok[i] === '(' ? ')' : '}', i);
      if (close === -1) return null;
      arg = tok.slice(i + 1, close);
      i = close + 1;
    } else {
      arg = tok[i++];
    }
    parts.push({ base, op, arg });
  }
  return parts.length ? parts : null;
}

/**
 * A bracketed base holds a formula — `(OH)`, `(m + 1)`, `(C2H5)` — never a
 * word. A bare run of letters in brackets is the parenthetical hint after a
 * fill-in-the-blank, and setting `(pursue)` as algebra would be worse than
 * leaving it alone.
 */
function plausibleBase(base) {
  for (const m of base.matchAll(/\(([^()]*)\)/g)) if (/^[A-Za-z]{3,}$/.test(m[1].trim())) return false;
  return base.length <= 24;
}

/** How many element symbols the token's letters resolve to, or 0 if not all. */
function elementCount(parts) {
  const bases = deHomoglyph(parts.map((p) => p.base).join(''));
  // A formula never opens with a digit: `9PS^2` is nine times PS squared.
  if (/^[0-9]/.test(bases)) return 0;
  // A bracketed radical is part of the formula — the `(OH)` of `Ca(OH)_(2)` —
  // so the brackets come out before the symbols are counted.
  const letters = bases.replace(/[0-9()\s+\-]/g, '');
  const symbols = letters.match(/[A-Z][a-z]?/g) || [];
  if (!symbols.length || symbols.join('') !== letters) return 0;
  return symbols.every((sym) => ELEMENTS.has(sym)) ? symbols.length : 0;
}

function scriptTokenToTex(tok, chemContext) {
  const parts = parseScriptToken(tok);
  if (!parts) return null;
  if (!parts.every((p) => plausibleBase(p.base || ''))) return null;
  const elements = elementCount(parts);
  // `^(12)C` — a mass number in front of a symbol is an isotope, and needs no
  // second formula in the sentence to prove it.
  const isotope = parts.length === 2 && !parts[0].base && parts[0].op === '^'
    && /^[0-9]{1,3}$/.test(parts[0].arg) && elements === 1;
  // Two element symbols make a formula on their own. A lone one — the O of
  // "release O_(2)" — only counts when the same sentence already had a formula,
  // otherwise S_(10) in a maths book would be set as sulphur.
  const chem = elements >= 2 || isotope || (chemContext && elements === 1);
  let tex = '';
  for (const p of parts) {
    let base = deHomoglyph(p.base || '').replace(/[−–—]/g, '-');
    // A bracketed base can carry scripts of its own: `(x^(2) + 2x)^(2)`.
    base = base.replace(/([_^])\(([^()\n]{1,16})\)/gu, (whole, op, arg) => {
      const a = scriptArg(arg);
      return a === null ? whole : `${op}{${a}}`;
    });
    if (/[_^]\(/.test(base)) return null;
    if (base) tex += chem ? `\\mathrm{${base}}` : base;
    if (!p.op) continue;
    const arg = scriptArg(p.arg, !!base);
    if (arg === null) return null;
    // A prefix script needs something to hang off, or KaTeX reads it as a
    // second script on whatever preceded it: `{}^{12}\mathrm{C}`.
    tex += `${base ? '' : '{}'}${p.op}{${arg}}`;
  }
  return mathOk(tex) ? tex : null;
}

// A base carrying at least one script. The base is usually a run of letters and
// digits, but the sources also hang scripts off a bracketed group (`Ca(OH)_(2)`,
// `(m + 1)^(th)`), off markdown emphasis (`*x*^(2)`), off Greek (`λ^(2)`), and
// off nothing at all (`^(12)C`). The bare form (`x^2`) takes a single character
// and must not be followed by more, so ordinary snake_case words are never
// mistaken for maths.
// One level of nesting, because a bracketed base carries scripts of its own:
// `(x^(2) + 2x)^(2)`. The alternatives start on different characters, so the
// repetition stays linear.
const GROUP = String.raw`\((?:[^()\n]|\([^()\n]{0,14}\)){1,28}\)`;
const BASE_UNIT = String.raw`(?:${GROUP}|[A-Za-z0-9Α-ωЀ-ӿ∆])+`;
const LEAD_BASE = String.raw`(?:\*[A-Za-z0-9Α-ωЀ-ӿ∆]{1,4}\*|${BASE_UNIT})`;
const SCRIPT_ARG = String.raw`(?:\([^()\n]{1,16}\)|\{[^{}\n]{1,16}\}|[A-Za-z0-9](?![A-Za-z0-9_]))`;
const ASCII_SCRIPT = new RegExp(`${LEAD_BASE}?(?:[_^]${SCRIPT_ARG}${LEAD_BASE}?)+`, 'gu');

// Touching an operator means the token is a fragment of a longer bare equation
// — `=a^2+2ab` — and wrapping just the fragment would break the line in three.
// That is a different problem; leave those whole. Brackets are not on the list:
// they group as often as they compute, and `A(x_(1), y_(1))` and "pentane
// (molecular formula C_(5)H_(12))" are both perfectly ordinary.
const OPERATOR_CONTEXT = /[=+*/<>^_\\|~]/;

// `<br>` ends a line all through this corpus. It is punctuation, not an
// operator, and a formula that happens to sit against one is still a formula.
const HTML_AFTER = /^<\/?[A-Za-z][^<>]{0,60}>/;
const HTML_BEFORE = /<\/?[A-Za-z][^<>]{0,60}>$/;

export function repairAsciiScripts(s) {
  if (!/[_^]/.test(s)) return s;
  const spans = mathSpans(s);
  // Backticked spans are shown verbatim; a subscript there is intended.
  for (const m of s.matchAll(/`+[^`]*`+/g)) spans.push([m.index, m.index + m[0].length]);
  const depth = braceDepths(s);

  const usable = (m) => {
    const tok = m[0];
    if (inSpan(spans, m.index) || depth[m.index] !== 0) return false;
    // A short base keeps `chapter_1`-style identifiers out of the maths.
    if (!/[({]/.test(tok) && !/^[A-Za-z0-9]{1,3}[_^]/.test(tok)) return false;
    const head = s.slice(0, m.index);
    const tail = s.slice(m.index + tok.length);
    const prev = HTML_BEFORE.test(head) ? ' ' : (head.at(-1) ?? ' ');
    const next = HTML_AFTER.test(tail) ? ' ' : (tail[0] ?? ' ');
    // `_____________(deliver)` — a script with no base, sitting on the end of a
    // fill-in-the-blank. The rule in the answer key is the blank, not a formula.
    if (/^[_^]/.test(tok) && /[_.]$/.test(head)) return false;
    // `2*x*^(2) + *x* – 4 = 0` — emphasis inside a bare equation. Setting this
    // one term as maths would leave the rest of the line as prose.
    if (tok.startsWith('*') && /[A-Za-z0-9]$/.test(prev)) return false;
    // A parenthetical gloss — "carbon dioxide (CO_(2))" — is prose, not algebra.
    if (prev === '(' && next === ')') return true;
    if (prev === '.' || prev === '/') return false; // path or filename
    return !OPERATOR_CONTEXT.test(prev) && !OPERATOR_CONTEXT.test(next);
  };

  // `p_(b)for vessel B` — a missing space glues an ordinary word onto the
  // token. A run of lower-case letters after the last script is prose, not a
  // formula; hand it back rather than setting "for" in italics.
  const trimProse = (m) => {
    const cut = /(?<=[)}\]0-9A-Za-z])[a-z]{2,}$/.exec(m[0]);
    if (!cut || /[_^]/.test(m[0].slice(cut.index))) return m;
    return { 0: m[0].slice(0, cut.index), index: m.index };
  };

  const found = [...s.matchAll(ASCII_SCRIPT)].map(trimProse).filter(usable);
  if (!found.length) return s;
  // One formula in the string settles the question for the rest of it.
  const chemContext = found.some((m) => {
    const parts = parseScriptToken(m[0]);
    return parts ? elementCount(parts) >= 2 : false;
  });

  let out = '';
  let cursor = 0;
  for (const m of found) {
    if (m.index < cursor) continue;
    const tex = scriptTokenToTex(m[0], chemContext);
    if (!tex) continue;
    const end = m.index + m[0].length;
    // `$\mathrm{Na}_{2}\mathrm{C}$О_(3)` — the formula was already half inside a
    // span. Growing that span is the repair; opening a second one against it
    // would leave `$$` in the line, which the tokenizer reads as display maths.
    // Only an inline span can be grown this way: a display delimiter is two
    // characters wide, and stepping over one of them leaves the other loose.
    // Against one of those the token takes its own pair, with a space to keep
    // the two pairs from reading as a single `$$`.
    const lone = (i) => s[i] === '$' && s[i - 1] !== '$' && s[i + 1] !== '$';
    const joinsLeft = spans.some(([, b]) => b === m.index) && lone(m.index - 1);
    const joinsRight = spans.some(([a]) => a === end) && lone(end);
    // `sin^(−1)$$\left( \cos\frac{\pi}{9} \right)$$` — the argument went into a
    // display block and the function name was left outside it. Kept apart they
    // reach the reader as `sin⁻¹` and then a centred line reading `(cos π/9)`,
    // with the sentence broken around it. They are one expression — nothing
    // stands between them, not even a space — so the block gives up its
    // delimiters instead of the token opening a second pair against them.
    const block = spans.find(([a]) => a === end && s.startsWith('$$', a));
    const body = block ? s.slice(end + 2, block[1] - 2) : '';
    // One line only: a block with rows in it was set on its own on purpose, and
    // a token glued to the front of one is a different fault from this.
    const absorb = !!block && !body.includes('\n') && mathOk(tex + body);
    out += s.slice(cursor, joinsLeft ? m.index - 1 : m.index);
    if (!joinsLeft) out += s[m.index - 1] === '$' ? ' $' : '$';
    out += tex;
    if (absorb) {
      out += `${body}$`;
      cursor = block[1];
    } else if (joinsRight) {
      cursor = end + 1;
    } else {
      out += s[end] === '$' ? '$ ' : '$';
      cursor = end;
    }
  }
  return cursor ? out + s.slice(cursor) : s;
}

// ------------------------------------------------ a formula split by its span
//
// `Ba($\mathrm{NO}_{3}$)_(2)` — the radical made it into a span and the count
// did not, so the reader gets `Ba(NO₃)_(2)`: half typeset, half source. Same
// for the hydrates, `$\mathrm{CuSO}_{4}$.5H_(2)O`. Neither piece is prose, so
// the repair is to pull them into the span the formula already has rather than
// open a second one against it.

// What can carry on a formula once the span closes: the closing bracket, a
// hydrate dot, more symbols, and the AsciiMath scripts themselves.
const SCRIPT_TAIL = /^(?:\)|\.(?=[0-9]*[A-Z])|[A-Za-z0-9]|[_^]\([^()\n]{1,12}\))+/;
// And what can lead into it: the metal of `Ba(NO3)2`, or a bare bracket.
const SCRIPT_HEAD = /(?:[A-Z][a-z]?|\()+$/;

/** Render `)_(2)SO_(4)` or `.5H_(2)O` as the TeX that continues a formula. */
function formulaFragmentToTex(fragment) {
  let tex = '';
  let i = 0;
  while (i < fragment.length) {
    const c = fragment[i];
    if (c === '(' || c === ')') { tex += c; i += 1; continue; }
    if (c === '.') { tex += '\\cdot '; i += 1; continue; }
    if (c === '_' || c === '^') {
      const close = fragment.indexOf(')', i + 2);
      if (fragment[i + 1] !== '(' || close === -1) return null;
      const arg = scriptArg(fragment.slice(i + 2, close));
      if (arg === null) return null;
      tex += `${c}{${arg}}`;
      i = close + 1;
      continue;
    }
    // A count is upright already; a symbol has to be told not to be italic. The
    // two are read separately so the `5` of `.5H_(2)O` stays outside the group.
    let word = '';
    if (/[0-9]/.test(c)) {
      while (i < fragment.length && /[0-9]/.test(fragment[i])) word += fragment[i++];
      tex += word;
      continue;
    }
    while (i < fragment.length && /[A-Za-z]/.test(fragment[i])) word += fragment[i++];
    if (!word) return null;
    tex += `\\mathrm{${word}}`;
  }
  return tex;
}

export function absorbScriptTail(s) {
  if (!s.includes('$') || !/[_^]\(/.test(s)) return s;
  const spans = mathSpans(s);
  if (!spans.length) return s;

  let out = '';
  let cursor = 0;
  for (const [a, b] of spans) {
    if (a < cursor) continue;
    const inner = s.slice(a + 1, b - 1);
    // Only chemistry writes this way, and only chemistry wants `\mathrm`. A
    // maths span with a stray `_(n)` after it is a different problem.
    if (!/\\ce\{|\\mathrm\{/.test(inner) || inner.startsWith('$')) continue;

    let tail = SCRIPT_TAIL.exec(s.slice(b))?.[0] ?? '';
    // `)_(2)solution` — a missing space glued a word on. Hand it back.
    tail = tail.replace(/(?<=[)0-9A-Za-z])[a-z]{3,}$/, '');
    if (!/[_^]\(/.test(tail)) continue;

    const head = SCRIPT_HEAD.exec(s.slice(cursor, a))?.[0] ?? '';
    const headTex = head ? formulaFragmentToTex(head) : '';
    const tailTex = formulaFragmentToTex(tail);
    if (headTex === null || tailTex === null) continue;
    if (!mathOk(headTex + inner + tailTex)) continue;

    out += s.slice(cursor, a - head.length) + `$${headTex}${inner}${tailTex}$`;
    cursor = b + tail.length;
  }
  return cursor ? out + s.slice(cursor) : s;
}

// A whole equation left in the prose: `y=x^2`, `(a+b)^2=a^2+2ab+b^2`. Taken as
// one run so it is never broken into pieces. It must carry both a script and an
// operator, which keeps ordinary sentences and plain arithmetic out.
// `*` is left out on purpose: it is markdown emphasis far more often than it is
// multiplication, and `**bold**` around a formula would be swallowed whole. `/`
// is left out because a media path — `.../images/img_5615778a2f8e.png` — has
// every other character an equation does, and wrapping one breaks the image.
const BARE_EXPR = /[A-Za-z0-9^_(){}[\]+\-=.,']{4,}/g;
const EXPR_OP = /[=+\-]/;

/** True when the whitespace-delimited word around [a,b) holds a backslash. */
function backslashWord(s, a, b) {
  let i = a;
  while (i > 0 && !/\s/.test(s[i - 1])) i -= 1;
  let j = b;
  while (j < s.length && !/\s/.test(s[j])) j += 1;
  return s.slice(i, j).includes('\\');
}

export function wrapBareExpressions(s) {
  if (!/[_^]/.test(s) || !EXPR_OP.test(s)) return s;
  const spans = mathSpans(s);
  for (const m of s.matchAll(/`+[^`]*`+/g)) spans.push([m.index, m.index + m[0].length]);
  // Inside a group the token is an argument of the command that owns it — the
  // `Cu^{2+}(aq)` of `\ce{Cu(s) -> Cu^{2+}(aq)}` — and a span there splits the
  // argument in half. `backslashWord` catches only the cases where the command
  // and the token share a whitespace-delimited word.
  const depth = braceDepths(s);
  let out = '';
  let cursor = 0;
  for (const m of s.matchAll(BARE_EXPR)) {
    if (inSpan(spans, m.index) || m.index < cursor || depth[m.index] !== 0) continue;
    // Trailing sentence punctuation belongs to the sentence, not the maths.
    const tok = m[0].replace(/[.,']+$/, '');
    if (tok.length < 4) continue;
    if (!/[_^]/.test(tok) || !EXPR_OP.test(tok)) continue;
    // A URL is not an equation, however much punctuation it shares with one.
    if (tok.includes('//') || /[:/]/.test(s[m.index - 1] ?? '')) continue;
    // `\boxed{\Delta T=2.5\times10^{-3}}` contains `times10^{-3}`, which parses
    // perfectly well on its own. Wrapping it would cut a command in half, so
    // stay out of any word that carries a backslash.
    if (backslashWord(s, m.index, m.index + tok.length)) continue;
    // AsciiMath scripts parse as something else entirely under KaTeX — `H_(2)O`
    // becomes H with a subscript bracket — so leave those to the pass below.
    if (/[_^]\(/.test(tok)) continue;
    if (!mathOk(tok)) continue;
    out += s.slice(cursor, m.index) + `$${tok}$`;
    cursor = m.index + tok.length;
  }
  return cursor ? out + s.slice(cursor) : s;
}

// Spacing/among-text commands are not worth wrapping on their own.
const TRIVIAL = /^\\(newline|quad|qquad|ldots|,|;|!|\s)?$/;

export function wrapBareCommands(s) {
  if (!s.includes('\\')) return s;
  const spans = mathSpans(s, true);
  // A command that sits inside a group — the `\max` of `f_{s,\max}`, the `\pi`
  // of `e^{-\pi}` — is part of a larger expression, so a span around it alone
  // would land a delimiter inside its own braces. Leave those to
  // wrapBareMathRuns, which can grow out to the whole expression.
  const depth = groupDepths(s);
  let out = '';
  let i = 0;
  while (i < s.length) {
    if (s[i] !== '\\' || !/[A-Za-z]/.test(s[i + 1] || '') || inSpan(spans, i) || depth[i] !== 0) {
      out += s[i++];
      continue;
    }
    const end = scanRun(s, i);
    const run = s.slice(i, end);
    if (run.length > 2 && !TRIVIAL.test(run)) {
      // A run may swallow an inner `$...$`; wrapping that as-is would nest
      // delimiters, so flatten it first and only keep the result if it parses.
      const flat = run.includes('$') ? run.replace(/\$/g, '') : run;
      if (mathOk(flat)) {
        // Butting a new span against an existing one would spell `$$`, which
        // means display math. Keep a space so the two stay separate spans.
        const lead = out.endsWith('$') ? ' ' : '';
        const tail = s[end] === '$' ? ' ' : '';
        out += `${lead}$${flat}$${tail}`;
        i = end;
        continue;
      }
    }
    out += run;
    i = end;
  }
  return out;
}

// What may sit *between* two commands without the run ceasing to be an
// equation: digits, operators, brackets and the punctuation maths uses. Letters
// are handled separately — a single one is a variable, two or more are a word.
const NEUTRAL = /[0-9+\-*/=<>()[\].,;:!'|°%±×÷≤≥≠→∞ \t]/;
const LETTER = /[A-Za-z]/;

/** True when the letter at `i` stands alone, so it reads as a variable. */
const loneLetter = (s, i) =>
  LETTER.test(s[i] || '') && !LETTER.test(s[i - 1] || '') && !LETTER.test(s[i + 1] || '');

const CLOSER = { ')': '(', ']': '[' };

/**
 * Length of `run` up to the first bracket it opens and never closes. Brackets
 * are neutral enough to grow a run across, but one the equation never closes
 * was the sentence's — `\ce{H2S} (or sulphur)` — and taking it makes the span
 * end on a stray `(`.
 */
function trimUnclosed(run) {
  const stack = [];
  for (let i = 0; i < run.length; i++) {
    if (run[i] === '\\') i += 1;
    else if (run[i] === '(' || run[i] === '[') stack.push(i);
    else if (CLOSER[run[i]] && stack.length) stack.pop();
  }
  return stack.length ? stack[0] : run.length;
}

/**
 * `1, 2, 3, \ldots, 31`, `m\in\mathbb N`, `A=(\sqrt A)^2`, `\dfrac83` — maths
 * written straight into a sentence, where the command run scanner stops at the
 * first digit or space and so never finds an expression KaTeX will accept.
 * Grows the run both ways over material that cannot be prose, and only keeps it
 * when the result parses.
 */
export function wrapBareMathRuns(s) {
  if (!s.includes('\\')) return s;
  const spans = mathSpans(s, true);
  for (const m of s.matchAll(/`+[^`]*`+/g)) spans.push([m.index, m.index + m[0].length]);
  const depth = braceDepths(s);
  let out = '';
  let cursor = 0;

  for (const m of s.matchAll(/(?<!\\)\\[A-Za-z]+/g)) {
    if (m.index < cursor || inSpan(spans, m.index)) continue;

    // Seeds sitting inside a group belong to whatever owns the group, so climb
    // out to its `{` before measuring: the span has to go round `f_{s,\max}`
    // whole, never round the `\max` on its own.
    let start = m.index;
    while (depth[start] > 0) {
      let k = start - 1;
      while (k >= 0 && !(s[k] === '{' && depth[k] === depth[start] - 1)) k -= 1;
      if (k < 0) break;
      start = k;
    }
    if (depth[start] !== 0) continue;

    while (start > 0) {
      // Standing on a group's `{`, the command in front of it owns the group:
      // a span that starts here would spell `\boxed${...}$`. Take the command.
      if (s[start] === '{') {
        const owner = /(?<!\\)\\[A-Za-z]+$/.exec(s.slice(0, start));
        if (owner) {
          start = owner.index;
          continue;
        }
      }
      const c = s[start - 1];
      if (c === '\n' || c === '$' || c === '*' || c === '`' || c === '\\') break;
      // A closed group to the left — the `e^{0}` of `e^{0}\cdot\sin 0` — joins
      // the run whole; stepping over just its `}` would unbalance it.
      if (c === '}') {
        const open = matchOpenBrace(s, start - 1);
        if (open < 0 || depth[open] !== 0) break;
        start = open;
        continue;
      }
      if (c === '_' || c === '^') {
        start -= 1;
        continue;
      }
      if (!loneLetter(s, start - 1) && !NEUTRAL.test(c)) break;
      start -= 1;
    }

    const seedEnd = Math.max(scanRun(s, m.index), start);
    let end = seedEnd;
    for (;;) {
      const c = s[end];
      if (c === undefined || c === '\n' || c === '$' || c === '*' || c === '`') break;
      // Closing a group the run itself opened. `start` is at depth 0, so a `}`
      // still nested here cannot belong to anything outside the run.
      if (c === '}' && depth[end] > 0) {
        end += 1;
        continue;
      }
      if (c === '\\' && LETTER.test(s[end + 1] || '')) {
        end = scanRun(s, end);
        continue;
      }
      if (c === '{' || c === '^' || c === '_') {
        const next = scanRun(s, end);
        if (next === end) break;
        end = next;
        continue;
      }
      if (loneLetter(s, end) || NEUTRAL.test(c)) {
        end += 1;
        continue;
      }
      break;
    }

    // Whitespace and sentence punctuation at either edge belong to the prose.
    while (start < m.index && /[\s,.;:!'|]/.test(s[start])) start += 1;
    end = start + trimUnclosed(s.slice(start, end));
    while (end > start && /[\s,.;:!']/.test(s[end - 1])) end -= 1;
    if (end < seedEnd) continue;

    const run = s.slice(start, end);
    if (depth[start] !== 0 || depth[end] !== 0) continue;
    if (run.length < 4 || TRIVIAL.test(run)) continue;
    // A single command with nothing around it is wrapBareCommands' business;
    // this pass exists for the material that scanner cannot reach.
    if (run === s.slice(m.index, scanRun(s, m.index))) continue;
    if (run.includes('//') || !mathOk(run)) continue;

    let pre = out + s.slice(cursor, start);
    let piece = `$${run}$`;
    // Butted against the span in front of it a new `$` would spell `$$`, which
    // opens display maths and swallows the rest of the line. An earlier pass
    // having already claimed half the expression — `($a^{m}$)^n = ...` — the
    // honest repair is to join the two, and failing that to keep them apart.
    if (pre.endsWith('$') && !pre.endsWith('$$')) {
      const open = pre.lastIndexOf('$', pre.length - 2);
      const body = open === -1 ? '' : pre.slice(open + 1, -1);
      if (body.trim() && !body.includes('\n') && mathOk(body + run)) {
        pre = pre.slice(0, -1);
        piece = `${run}$`;
      } else {
        piece = ` ${piece}`;
      }
    }
    out = pre + piece + (s[end] === '$' ? ' ' : '');
    cursor = end;
  }
  return cursor ? out + s.slice(cursor) : s;
}

// ------------------------------------------------------------------- cleanup

export function stripControl(s) {
  if (!HAS_CTRL.test(s)) return s;
  return s
    .replace(new RegExp(`(?<=\\$)[${C}]+(?=\\$)`, 'g'), ' ')
    .replace(CTRL_RUN, '');
}

// --------------------------------------------- unsupported glyphs *in math*

// Outside math these render fine in the browser; only KaTeX lacks metrics, so
// the substitution is deliberately confined to math spans.
const GLYPHS = new Map([
  ['½', '\\frac{1}{2}'],
  ['¼', '\\frac{1}{4}'],
  ['¾', '\\frac{3}{4}'],
  ['★', '\\bigstar'],
  ['■', '\\blacksquare'],
  ['□', '\\square'],
  ['•', '\\bullet'],
  ['●', '\\bullet'],
  ['∆', '\\Delta'],
  ['″', "''"],
]);
const GLYPH_RE = new RegExp(`[${[...GLYPHS.keys()].join('')}]`, 'g');

// Commands whose backslash is simply gone, plus the tails a C escape left when
// it ate the backslash *and* the first letter (`\frac` -> FF + "rac"). Both
// forms parse as a run of variables followed by a group, so KaTeX never
// complains — it just renders `rac{1}{9}` as the letters r, a, c.
const LOST = new Map([
  ['operatorname', 'operatorname'],
  ['underline', 'underline'],
  ['overline', 'overline'],
  ['textrm', 'textrm'],
  ['textbf', 'textbf'],
  ['textit', 'textit'],
  ['mathrm', 'mathrm'],
  ['mathbf', 'mathbf'],
  ['extrm', 'textrm'],
  ['extbf', 'textbf'],
  ['extit', 'textit'],
  ['dfrac', 'dfrac'],
  ['tfrac', 'tfrac'],
  ['binom', 'binom'],
  ['boxed', 'boxed'],
  ['sqrt', 'sqrt'],
  ['frac', 'frac'],
  ['text', 'text'],
  ['ext', 'text'],
  ['rac', 'frac'],
  ['vec', 'vec'],
  ['hat', 'hat'],
]);
// Longest first, so `extrm{` is never read as `ext` + "rm{".
const LOST_RE = new RegExp(
  `(?<![\\\\A-Za-z])(${[...LOST.keys()].sort((a, b) => b.length - a.length).join('|')})\\{`,
  'g',
);

/**
 * The same lost-backslash damage, but in prose, where no math span exists to
 * hand to fixGlyphsInTex. A string opening `ext{--}I effect but directs...` is a
 * `\text{--}` whose backslash and `t` the control byte ate; restoring it lets
 * the bare-command wrapper put the fragment back into maths.
 */
export function repairLostInProse(s) {
  if (!s.includes('{')) return s;
  const spans = mathSpans(s);
  return s.replace(LOST_RE, (whole, name, i) =>
    inSpan(spans, i) ? whole : `\\${LOST.get(name)}{`,
  );
}

function fixGlyphsInTex(tex) {
  let t = tex.replace(GLYPH_RE, (c) => GLYPHS.get(c));
  t = t.replace(LOST_RE, (_, name) => `\\${LOST.get(name)}{`);
  // ∛x -> \sqrt[3]{x}
  t = t.replace(/∛\s*(\{[^{}]*\}|[A-Za-z0-9.]+)/g, (_, arg) => {
    const inner = arg.startsWith('{') ? arg.slice(1, -1) : arg;
    return `\\sqrt[3]{${inner}}`;
  });
  return t;
}

// ------------------------------------------------- malformed math internals

/** How many `{` are still open at the end of a fragment (negative if over-closed). */
function braceBalance(x) {
  let depth = 0;
  for (let i = 0; i < x.length; i++) {
    if (x[i] === '\\') i++;
    else if (x[i] === '{') depth++;
    else if (x[i] === '}') depth--;
  }
  return depth;
}

/** Delete `}` that closes nothing — the residue of a wrapper we removed. */
function dropUnmatchedCloses(x) {
  let depth = 0;
  let out = '';
  for (let i = 0; i < x.length; i++) {
    const c = x[i];
    if (c === '\\') {
      out += c + (x[i + 1] ?? '');
      i++;
      continue;
    }
    if (c === '{') depth++;
    else if (c === '}') {
      if (depth === 0) continue;
      depth--;
    }
    out += c;
  }
  return out;
}

function fixTexBody(tex, displayMode) {
  let t = tex;
  if (mathOk(t, displayMode)) return t;

  const attempts = [];
  // A stray `$` inside a display block is a delimiter that leaked in.
  if (t.includes('$')) attempts.push(t.replace(/\$/g, ''));
  // A literal \n that should have been a row break, or just whitespace.
  if (/\\n(?![A-Za-z])/.test(t)) {
    attempts.push(t.replace(/\\n(?![A-Za-z])/g, '\\\\'));
    attempts.push(t.replace(/\\n(?![A-Za-z])/g, ' '));
  }
  // A `\text{...` whose closing brace was eaten along with the delimiter that
  // followed it. Closing the group is the only reading that makes sense.
  const open = braceBalance(t);
  if (open > 0 && open <= 3) attempts.push(t + '}'.repeat(open));
  if (open < 0) attempts.push(dropUnmatchedCloses(t));
  // Fill-in-the-blank underscores are text, not subscripts.
  if (/_{2,}/.test(t)) attempts.push(t.replace(/_{2,}/g, (u) => '\\_'.repeat(u.length)));
  // \centernot is not in KaTeX; \not is the supported spelling.
  if (t.includes('\\centernot')) attempts.push(t.replace(/\\centernot/g, '\\not'));
  // \tfrac is unavailable in text mode.
  if (t.includes('\\tfrac')) attempts.push(t.replace(/\\tfrac/g, '\\frac'));
  // The generator sometimes stuttered, reopening \text{ several times over the
  // same content. Only the innermost payload was ever meant.
  if (/(\\text\{\s*){2,}/.test(t)) {
    const unwrapped = t.replace(/^(?:\s*\\text\{\s*)+/, '');
    attempts.push(unwrapped.replace(/\}+\s*$/, ''));
    attempts.push(dropUnmatchedCloses(unwrapped));
  }
  // Math commands stranded inside \text{...} need their own math shell.
  if (/\\text\{[^{}]*\\[a-zA-Z]/.test(t)) {
    attempts.push(
      t.replace(/\\text\{([^{}]*)\}/g, (m0, inner) =>
        /\\[a-zA-Z]/.test(inner)
          ? `\\text{${inner.replace(/\\[a-zA-Z]+\d*/g, (c) => `$${c}$`)}}`
          : m0,
      ),
    );
  }
  // `\begin{array}x & 1 & 2` lost its column specification entirely.
  if (/\\begin\{array\}(?!\s*\{)/.test(t)) {
    const firstRow = t.split(/\\\\/)[0] || '';
    const cols = Math.max(1, (firstRow.match(/&/g) || []).length + 1);
    attempts.push(t.replace(/\\begin\{array\}/g, `\\begin{array}{${'c'.repeat(cols)}}`));
  }

  for (const a of attempts) if (mathOk(a, displayMode)) return a;
  // Combinations, for strings with more than one defect.
  let combo = t
    .replace(/\\n(?![A-Za-z])/g, ' ')
    .replace(/_{2,}/g, (u) => '\\_'.repeat(u.length))
    .replace(/\\centernot/g, '\\not')
    .replace(/\\tfrac/g, '\\frac');
  if (mathOk(combo, displayMode)) return combo;
  combo = combo.replace(/\$/g, '');
  if (mathOk(combo, displayMode)) return combo;
  return t;
}

/** Rewrite every math span in a string: glyph mapping plus targeted repairs. */
export function repairMath(s) {
  if (!s.includes('$')) return s;
  const code = [];
  if (s.includes('`')) {
    for (const m of s.matchAll(CODE_SPAN)) code.push([m.index, m.index + m[0].length]);
  }
  return s.replace(/\$\$[\s\S]*?\$\$|(?<!\\)\$[^$\n]*?(?<!\\)\$/g, (seg, at) => {
    if (code.some(([a, b]) => at < b && at + seg.length > a)) return seg;
    // A bare `$$` is an empty *inline* pair, not the opening of a display block:
    // reading it as display makes the body `seg.slice(2, 0)`, and rewriting it
    // as `open + body + open` doubles the delimiters into `$$$$`.
    const display = seg.startsWith('$$') && seg.length >= 4;
    const open = display ? '$$' : '$';
    const body = seg.slice(open.length, seg.length - open.length);
    const fixed = fixTexBody(fixGlyphsInTex(body), display);
    // Hard invariant: a rewrite may never turn working math into broken math.
    if (fixed !== body && mathOk(body, display) && !mathOk(fixed, display)) return seg;
    return `${open}${fixed}${open}`;
  });
}

// Markdown claims code spans before math, so a `$` inside backticks is a
// literal dollar (a PHP variable, a shell prompt) and is never typeset.
const CODE_SPAN = /`+[^`]*`+/g;
const maskCodeSpans = (s) => (s.includes('`') ? s.replace(CODE_SPAN, (m) => ' '.repeat(m.length)) : s);

/**
 * Split a string into the math the page will try to typeset — using the site's
 * own tokenizer, not an approximation of it. A hand-rolled regex disagrees with
 * the shipped one on exactly the awkward cases this tool is here to judge, and
 * the shipped one is what decides whether a reader sees a formula or red source.
 */
export function mathSegments(text) {
  return tokenize(normalizeText(text))
    .filter((t) => t.kind === 'math')
    .map((t) => ({ tex: t.value, display: t.display }));
}

/**
 * How many math spans a reader would see fail. `relaxed` is the forgiving
 * cleanup the renderer applies last (it closes braces, drops stray `$`, escapes
 * `&`), so a repair must be judged after it, not before.
 */
export function countMathFailures(s) {
  if (!s.includes('$') && !HAS_CTRL.test(s)) return 0;
  let n = 0;
  for (const t of tokenize(normalizeText(s))) {
    if (t.kind !== 'math') continue;
    if (!mathOk(relaxed(t.value, t.display), t.display)) n++;
  }
  return n;
}

const SINGLE_DOLLAR = /(?<!\$)\$(?!\$)/g;

// Commands that legitimately carry words, plus the command names themselves:
// what is left after removing them is the span's own content.
const WORD_COMMANDS =
  /\\(?:text|textrm|textbf|textit|textsf|mathrm|mathbf|mathit|operatorname\*?|ce|mbox|hbox)\s*\{[^{}]*\}/g;
// A lower-case word is prose. Capitals are left out: `\triangle BDE`
// and `\angle ABC` name vertices, and two letters are `dx` or `cm`.
const PROSE_WORD = /[a-z]{3,}/;

/** True when a span's body reads as a sentence rather than as an equation. */
function proseSpan(body) {
  const rest = body.replace(WORD_COMMANDS, '').replace(/\\[A-Za-z]+/g, '');
  if (PROSE_WORD.test(rest)) return true;
  // Devanagari, Tamil, Gujarati: scripts no equation is ever written in, so a
  // single letter from one is enough. Greek stays below the cut, being maths.
  for (const ch of rest) {
    if (ch.codePointAt(0) > 0x3ff && /\p{L}/u.test(ch)) return true;
  }
  return false;
}

// Lower is better, compared left to right: a stranded delimiter is the worst
// outcome, then anything the reader would see fail, then maths left outside a
// span, then empty formula boxes. Length comes last and prefers the *longer*
// string, so a delimiter is only ever deleted when doing so wins on one of the
// keys above — an unterminated `$$` reads as maths to the tokenizer and would
// otherwise look like a cheap improvement.
function spanScore(x) {
  let mathChars = 0;
  let empties = 0;
  let lopsided = 0;
  let stray = 0;
  let prose = 0;
  for (const t of tokenize(normalizeText(x))) {
    if (t.kind !== 'math') {
      // `$$` that never paired is not a delimiter to the tokenizer, so the
      // reader is simply shown the dollars. Nothing else here is worth that.
      stray += (String(t.value).match(/(?<!\\)\$/g) || []).length;
      continue;
    }
    const body = String(t.value).trim();
    if (body) mathChars += body.length;
    else empties++;
    // Words with nothing an equation uses in them — ` and `, ` तथा ` — are the
    // sentence the two delimiters happen to sit either side of, not a formula.
    // Left to the length keys below they would always win, prose being longer
    // than the maths beside it.
    if (proseSpan(body)) prose++;
    // A display span closed by a single `$` renders, so KaTeX never objects,
    // but it means a delimiter went missing and the leftover will pair with
    // whatever comes next. Weigh that above everything but a stranded `$`.
    const d = t.display ? '$$' : '$';
    if (!t.raw.startsWith(d) || !t.raw.endsWith(d) || t.raw.length < 2 * d.length) lopsided++;
  }
  return [
    // `\$` is a printed dollar sign, not a delimiter, so it must not shift the
    // parity: `Loss\$% = $a$ $b$ 100$` has five delimiters and one spare, and
    // counting the escaped one makes the spare look like a matched pair.
    (x.match(/(?<!\\)\$/g) || []).length % 2,
    lopsided,
    stray,
    countMathFailures(x),
    prose,
    -mathChars,
    empties,
    -x.length,
  ];
}

const scoreBetter = (a, b) => {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] < b[i];
  return false;
};

/**
 * A `$` the generator wrote twice — `$ $\boxed{x}$`, `$\n$\left(...\right)$`.
 * The doubled pair frames nothing, so the reader gets an empty formula box and
 * every delimiter after it pairs one position out, spilling the rest of the
 * line as raw source.
 *
 * Which half of the doubling was the mistake is not decidable locally: in
 * `$ $\boxed{A}$ $` both empty pairs are really one delimiter each, while in
 * `$\n$$X$$\n$` both are junk framing a display block. So each empty pair is
 * tried both ways and the combination the site's own tokenizer likes best wins
 * — most maths recovered, nothing left unparseable, no dangling delimiter.
 */
export function dropEmptySpans(s) {
  if (!s.includes('$')) return s;
  // Nothing but delimiters. `$$$$` never pairs into a span at all, so the reader
  // is shown the four dollars verbatim; only the whitespace was ever content.
  if (/^[\s$]*$/.test(s)) return s.replace(/\$/g, '');
  const toks = [...tokenize(normalizeText(s))];
  // Rebuild has to be lossless, or the splice would move unrelated text.
  if (toks.map((t) => t.raw).join('') !== s) return s;
  const empty = (t) => t.kind === 'math' && !String(t.value).trim();
  const slots = toks.map((t, i) => (empty(t) ? i : -1)).filter((i) => i >= 0);
  // Beyond a handful the enumeration stops being cheap, and a string with five
  // empty spans is damaged past what a delimiter reshuffle can rescue.
  if (!slots.length || slots.length > 4) return s;

  // What a single empty pair can become. Either it framed nothing and only the
  // whitespace survives, or it was one delimiter written twice — in which case
  // the whitespace belongs outside the span it opens or closes, never inside:
  // a span whose body starts with a newline is one several later passes decline
  // to look into, and the tokenizer will not pair `$$` written as `$` + `\n$`.
  const ACTIONS = [
    (t) => t.value,
    (t) => t.value + (t.display ? '$$' : '$'),
    (t) => (t.display ? '$$' : '$') + t.value,
  ];

  const build = (combo) => {
    let out = '';
    for (let i = 0; i < toks.length; i++) {
      const t = toks[i];
      const slot = slots.indexOf(i);
      out += slot === -1 ? t.raw : ACTIONS[Math.floor(combo / 3 ** slot) % 3](t);
    }
    // A surviving opener can leave its far partner stranded — `$\n$ ... \n$`.
    // A lone `$` with only whitespace after it swallows the rest of the line.
    const singles = [...out.matchAll(SINGLE_DOLLAR)];
    if (singles.length % 2 === 1) {
      const last = singles[singles.length - 1].index;
      if (!out.slice(last + 1).trim()) out = out.slice(0, last) + out.slice(last + 1);
    }
    return out;
  };

  let best = s;
  let bestScore = spanScore(s);
  for (let combo = 0; combo < 3 ** slots.length; combo++) {
    const cand = build(combo);
    if (cand === s) continue;
    const sc = spanScore(cand);
    if (scoreBetter(sc, bestScore)) {
      best = cand;
      bestScore = sc;
    }
  }
  return best;
}

/**
 * A `$` with no partner. The tokenizer pairs delimiters left to right and drops
 * whatever is left over, so a single extra one is never shown as maths: it is
 * printed verbatim, and everything it should have opened stays raw. They arrive
 * two ways — a marker whose other half the corruption ate (`␛[KaTeX]The
 * identity holds:\n$$...$$`), and an earlier pass promoting inline to display
 * over a delimiter the source had already written (`$...$` spanning newlines
 * becomes `$$...$$$`).
 *
 * Which `$` is the spare is not decidable by position — the leading one is
 * wrong in the first case and the trailing one in the second — so each is tried
 * in turn and scored the way the empty-span pass scores its own candidates.
 */
/**
 * `$(i)\ a^2+b^2=26$, \quad $(ii)\ ab=5$` — a page-spacing command left between
 * two finished spans. KaTeX never sees it, so the reader is shown the source,
 * and the gap it was asking for is already there as an ordinary space.
 *
 * Prose is whatever the site's own tokenizer hands to the reader as text, so
 * that is what decides; a `\quad` the wrapping passes pulled into a span keeps
 * its meaning and is left alone. Arrays are exempt whole: inside one the
 * spacing *is* the content — a number pyramid is built out of `\qquad` — and a
 * grid the reader is already being shown raw is not improved by flattening it.
 */
// Every spacing command, not just the wide ones: a span that closed a few
// characters early leaves `BC = 6\, cm` in the prose, and `\,` prints as itself.
const ORPHAN_SPACING = /[ \t]*(?<!\\)\\(?:q?quad|[,;:])(?![A-Za-z])[ \t]*/g;
// `\!` asks for negative space. A gap is not a smaller version of that, so it
// goes without leaving one behind.
const ORPHAN_NEGATIVE = /(?<!\\)\\!(?![A-Za-z])/g;

// An ellipsis command that no wrapper would take. This runs last, so anything
// still in a text token here has already been declined by every pass that could
// have given it delimiters; the character it stands for is what the reader
// wanted, and `\ldots` is not.
const ORPHAN_ELLIPSIS = /(?<!\\)\\(?:ldots|cdots|dots|dotsc)(?![A-Za-z])/g;

export function dropOrphanSpacing(s) {
  if (!/(?<!\\)\\(?:q?quad|l?dots|cdots|dotsc|[,;:!])(?![A-Za-z])/.test(s)) return s;
  const toks = [...tokenize(normalizeText(s))];
  if (toks.map((t) => t.raw).join('') !== s) return s;
  return toks
    .map((t) => {
      // A run carrying `\boxed{…}`, `\frac{…}` or `\begin{bmatrix}` is maths
      // that never got its delimiters, not prose. The spacing in it is doing its
      // job; the wrapping passes are what that run needs. Testing the token
      // rather than the whole string matters: a matrix in a span of its own must
      // not stop the sentence beside it from being tidied.
      if (t.kind === 'math' || /\\[A-Za-z]+\s*\{/.test(t.raw)) return t.raw;
      // The spaces on either side go with it: what the command asked for was
      // one gap, and leaving both behind doubles it.
      return t.raw
        .replace(ORPHAN_SPACING, ' ')
        .replace(ORPHAN_NEGATIVE, '')
        .replace(ORPHAN_ELLIPSIS, '…');
    })
    .join('');
}

const FENCE_WORD = /\\(?:left|right)(?![A-Za-z])/g;
const FENCE_NOTHING = /\\(?:left|right)\s*\./g;

/**
 * `\left` and `\right` come as a pair or not at all: KaTeX rejects either one
 * alone, so a string holding half of one — the generator split the equation
 * across two of them, `…is \left(` then `…\right).` — renders as source on both
 * sides. Dropping the sizing keeps the delimiter and the sentence; there is
 * nothing to size against once the partner is in another string.
 */
export function dropOrphanFences(s) {
  if (!/\\(?:left|right)(?![A-Za-z])/.test(s)) return s;
  const toks = [...tokenize(normalizeText(s))];
  if (toks.map((t) => t.raw).join('') !== s) return s;
  return toks
    .map((t) => {
      const opens = (t.raw.match(/\\left(?![A-Za-z])/g) || []).length;
      const closes = (t.raw.match(/\\right(?![A-Za-z])/g) || []).length;
      if (opens === closes) return t.raw;
      // `\left.` and `\right.` are the invisible ones: the delimiter they name
      // is nothing, so the command and its dot go together.
      return t.raw.replace(FENCE_NOTHING, '').replace(FENCE_WORD, '');
    })
    .join('');
}

// Inside a `\text{…}` body the seams run the other way round: a `}` opens a
// stretch of maths and the next `\text{` closes it again.
const TORN_SEAM = /\}([^{}]*?)\\text\s*\{/g;

/**
 * `…के लिए }3\text{ का घातांक }3\text{ होना चाहिए, इसलिए }3^2=9\text{ से गुणा`
 * — the tail of a `\text{…}` body split across two blocks. The opening command
 * went with the block before, so what is left starts in the middle of a text
 * argument and every brace in it is inside out. The reader is shown the seams.
 *
 * The seams are still readable, though: between a `}` and the next `\text{` is
 * maths, and everything else is prose. That is a span each, which is what the
 * whole block would have rendered as had it not been cut in two.
 */
export function mendTornText(s) {
  if (!/\}[^{}]*?\\text\s*\{/.test(s)) return s;
  const toks = [...tokenize(normalizeText(s))];
  if (toks.map((t) => t.raw).join('') !== s) return s;
  let mended = false;
  const out = toks
    .map((t) => {
      // Only a run whose first brace is a *closing* one has lost its opener;
      // anywhere else the braces are the author's and mean what they say.
      if (t.kind === 'math' || (/[{}]/.exec(t.raw) ?? [''])[0] !== '}') return t.raw;
      let ok = true;
      const fixed = t.raw.replace(TORN_SEAM, (whole, body) => {
        if (!body.trim() || !mathOk(body)) ok = false;
        return `$${body}$`;
      });
      // The body ends where the block was cut, so the last `\text{` has no `}`
      // and never had one here. It renders as nothing; the prose after it is
      // the point.
      const tail = fixed.replace(/\\text\s*\{(?![\s\S]*[{}])/, '');
      if (!ok || braceBalance(tail) !== 0) return t.raw;
      mended = true;
      return tail;
    })
    .join('');
  return mended ? out : s;
}

/**
 * `U_{s}=\frac12kx^2=…\text{J}.\n$$\nHence,\n$$\n\boxed{…}.\n$$` — three display
 * delimiters, so one block has lost an end. The site renders each block on its
 * own, so the odd one out never pairs: the maths at that end is handed to the
 * reader as source, and the wrapping passes then shred it into a span per
 * fragment. Giving it back the delimiter it lost is one character and undoes
 * all of that.
 */
export function closeTornDisplay(s) {
  const marks = s.match(/\$\$/g);
  if (!marks || marks.length % 2 === 0) return s;
  // Prose is not a lost display block, and neither is anything holding an
  // inline span — the odd `$` there is a different fault. A fenced code block
  // is not one either: `$$```\n 67\n\times 18\n─────` is a long multiplication
  // set as ASCII art, and closing a display round it would hand the fence and
  // the rule to KaTeX. There the stray `$$` is the damage, not the missing one.
  const lost = (part) =>
    part.trim() &&
    /\\[A-Za-z]/.test(part) &&
    !/(?<![\\$])\$(?!\$)/.test(part) &&
    !part.includes('```') &&
    mathOk(part.trim(), true);
  const first = s.indexOf('$$');
  const head = s.slice(0, first);
  if (lost(head)) return `$$\n${head.trim()}\n${s.slice(first)}`;
  const last = s.lastIndexOf('$$');
  const tail = s.slice(last + 2);
  if (lost(tail)) return `${s.slice(0, last + 2)}\n${tail.trim()}\n$$`;
  return s;
}

// A string that is nothing but the end of an expression: it opens with a
// command, so it is not prose that happens to carry one.
const TORN_HEAD = /^\s*\\[A-Za-z]+\s*[{[]/;

/**
 * `\boxed{s=-0.20\,\text{m}}\quad\text{(i.e. the block moves }0.20\,\text{m
 * downward in the ground frame).` — the closing brace of the last group never
 * made it into the block. Nothing in the string parses without it and the whole
 * answer is shown as source. One brace puts it back; more than one is guesswork
 * about structure that is no longer here, and is left alone.
 */
export function closeTornGroups(s) {
  if (s.includes('$') || !TORN_HEAD.test(s) || braceBalance(s) !== 1) return s;
  return !mathOk(s) && mathOk(`${s}}`) ? `${s}}` : s;
}

// `\textsubscript` is a LaTeX-document command with no KaTeX spelling, but the
// script it asks for is one KaTeX has had all along.
const TEXT_SCRIPT = /\\text(sub|super)script\s*\{([^{}]*)\}/g;

export function normalizeTextScripts(s) {
  if (!s.includes('\\text')) return s;
  const toks = [...tokenize(normalizeText(s))];
  if (toks.map((t) => t.raw).join('') !== s) return s;
  return toks
    .map((t) =>
      t.raw.replace(TEXT_SCRIPT, (whole, which, body) => {
        const script = `${which === 'sub' ? '_' : '^'}{\\text{${body}}}`;
        return t.kind === 'math' ? script : `$${script}$`;
      }),
    )
    .join('');
}

/**
 * `\text{2\,\mathrm{s}}` is valid LaTeX and a parse error in KaTeX, which has no
 * text-mode `\mathrm`. One command in the wrong mode fails the whole expression,
 * so no wrapper will touch it and the reader is shown `\boxed{\text{…}}` as
 * source — which is what most of the leaked-LaTeX tail turns out to be.
 *
 * Inside `\text{…}` the alphabet is already upright, so the wrapper is saying
 * nothing and dropping it changes nothing on the page. `\mathbf`/`\mathit` do
 * mean something, and have text-mode spellings to move to.
 */
const TEXT_DEGREE = /(?:\{\})?\^\s*(?:\{\s*\\circ\s*\}|\\circ(?![A-Za-z]))/g;

/** The text-mode repairs, for one stretch of a `\text{…}` body. */
const textMode = (part) =>
  part
    .replace(TEXT_DEGREE, '°')
    // `16%` comments out the rest of the expression, braces and all, so a
    // per-cent sign in a sentence takes the whole answer down with it.
    .replace(/(?<!\\)%/g, '\\%')
    // The space guards a collision: `\,\mathrm{C}` after a command must not lose
    // its braces and weld into `\circC`, which does not exist. Only a letter
    // landing straight after a letter-command needs it.
    .replace(/\\(?:mathrm|textrm|mathsf|mathtt)\s*\{([^{}]*)\}/g, (whole, inner, at, all) =>
      /\\[A-Za-z]+$/.test(all.slice(0, at)) && /^[A-Za-z]/.test(inner) ? ` ${inner}` : inner,
    )
    .replace(/\\mathbf\s*\{([^{}]*)\}/g, '\\textbf{$1}')
    .replace(/\\mathit\s*\{([^{}]*)\}/g, '\\textit{$1}');

const NESTED_SPAN = /(\$[^$]*\$)/;

/**
 * The body of one `\text{…}`, in the two readings a nested `$…$` allows.
 *
 * `\text{at $2\,\mathrm{s}$}` is valid LaTeX, but the site tokenizer has no way
 * to know the span is nested: it ends the outer one there and shows the rest of
 * the sentence as source. Absorbing the island into text mode is the reading
 * that keeps the sentence in one piece — `2\,\mathrm{s}` is upright either way.
 * `flat` is the fallback for an island that means something in maths and
 * nothing in text: `}…\text{` is the same nesting expressed in braces.
 */
function fixTextBody(body) {
  // mhchem has no text-mode spelling either, so a formula is an island in its
  // own right even with no delimiters around it to say so.
  const marked = body
    .split(NESTED_SPAN)
    .map((part, i) => (i % 2 ? part : part.replace(/\\ce\s*\{[^{}]*\}/g, '$$$&$$')))
    .join('');
  const parts = marked.split(NESTED_SPAN);
  return {
    absorbed: parts.map((part, i) => textMode(i % 2 ? part.slice(1, -1) : part)).join(''),
    flat: parts.map((part, i) => (i % 2 ? `}${part.slice(1, -1)}\\text{` : textMode(part))).join(''),
    nested: parts.length > 1,
  };
}

export function unnestTextCommands(s) {
  if (!/\\text(?:rm)?\s*\{/.test(s)) return s;
  if (!/\\math(?:rm|bf|it|sf|tt)\s*\{|\^\s*\{?\s*\\circ|\\ce\s*\{|[$%]/.test(s)) return s;
  const re = /\\text(?:rm)?\s*\{/g;
  let out = '';
  let cursor = 0;
  let nested = false;
  let m;
  while ((m = re.exec(s)) !== null) {
    const open = m.index + m[0].length - 1;
    const close = matchBrace(s, open);
    if (close < 0) continue;
    const body = s.slice(open + 1, close);
    const candidate = fixTextBody(body);
    // Absorbing is preferred and has to be earned: the island only belongs in
    // text mode if what comes out of it still parses there.
    const fixed =
      candidate.nested && !mathOk(`\\text{${candidate.absorbed}}`) ? candidate.flat : candidate.absorbed;
    if (fixed === body) continue;
    if (candidate.nested) nested = true;
    out += s.slice(cursor, open + 1) + fixed;
    cursor = close;
    // Skip past the group just rewritten: an inner `\text{…}` went with it.
    re.lastIndex = close;
  }
  if (!out) return s;
  // An island at the end of a body leaves `\text{` for the group's own `}` to
  // close. It renders as nothing either way; dropping it keeps the source clean.
  const result = (out + s.slice(cursor)).replace(/\\text\s*\{\}/g, '');
  // A string whose only delimiters were the nested ones now has none, and the
  // wrappers downstream would read the `}…\text{` seam as the end of a run and
  // span the halves separately. It is one expression; it gets one pair.
  if (nested && !result.includes('$') && mathOk(result)) return `$${result}$`;
  return result;
}

/**
 * U+FFFD is a byte that did not survive the source's encoding, and nothing can
 * be recovered from it. The sentence reads correctly without it: "lines �1 and
 * �2 intersect at O" was "lines l₁ and l₂", and "lines 1 and 2" is still true —
 * whereas the replacement glyph itself is visible nonsense.
 */
export function dropReplacementChar(s) {
  return s.includes('�') ? s.replace(/�/g, '') : s;
}

/**
 * Like `braceDepths`, but a `{` that never closes counts for nothing. In
 * `$\frac12\times\text{आधार}\times\text{ऊँचाई$` the group is torn — the block was
 * cut before its `}` — so the `$` after it is the span's own closing delimiter,
 * not one nested inside an argument. Reading it as nested costs the expression
 * its span, whereas the missing brace is something `repairMath` puts back.
 */
function closedBraceDepths(s) {
  const open = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\') i += 1;
    else if (s[i] === '{') open.push(i);
    else if (s[i] === '}' && open.length) open.pop();
  }
  const torn = new Set(open);
  const depth = new Array(s.length + 1).fill(0);
  for (let i = 0, d = 0; i < s.length; i++) {
    if (s[i] === '\\') depth[++i] = d;
    else if (s[i] === '{') { if (!torn.has(i)) d++; }
    else if (s[i] === '}') d = Math.max(0, d - 1);
    depth[i + 1] = d;
  }
  return depth;
}

/**
 * A `$` inside a brace group. No span can legitimately open there — `\frac{` is
 * mid-command — so `\frac{$m_{2}$-$m_{1}$}{1+m_1m_2}` is a source that had its
 * sub-terms spanned individually and then got pasted into a larger expression.
 * The delimiters are the damage; the expression around them is sound.
 */
export function dropNestedDollars(s) {
  if (!s.includes('$') || !/\\[A-Za-z]+\s*\{/.test(s)) return s;
  const depth = closedBraceDepths(s);
  let out = '';
  let dropped = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\') { out += s.slice(i, i + 2); i += 1; continue; }
    if (s[i] === '$' && depth[i] > 0) { dropped += 1; continue; }
    out += s[i];
  }
  if (!dropped) return s;
  return countMathFailures(out) <= countMathFailures(s) ? out : s;
}

const CURRENCY = /(?:^|[\s(])\$\d/;

export function dropStrayDollar(s) {
  const at = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\') i += 1;
    else if (s[i] === '$') at.push(i);
  }
  // An even count pairs up. It may still pair *wrongly*, but then the fix is a
  // delimiter in the right place, which is not something this pass can invent.
  if (at.length % 2 === 0) return s;
  // Long strings are the ones with many spans, where a single spare delimiter
  // is a rounding error against the cost of scoring every position.
  if (at.length > 24) return s;

  let best = s;
  let bestScore = spanScore(s);
  for (const i of at) {
    // `Rs 200 or $5 each` — a price, and the only `$` in the sentence, so it is
    // the odd one out by construction and every key below would vote to delete
    // it. An opener would have a closer somewhere; this one is the symbol.
    if (CURRENCY.test(s.slice(Math.max(0, i - 1), i + 3))) continue;
    const cand = s.slice(0, i) + s.slice(i + 1);
    const sc = spanScore(cand);
    if (scoreBetter(sc, bestScore)) {
      best = cand;
      bestScore = sc;
    }
  }
  return best;
}

// Only tidy the whitespace that our own deletions created. Running this over
// untouched prose would rewrite tens of thousands of perfectly good strings.
const tidy = (t) => t.replace(/[ \t]{2,}/g, ' ').replace(/ +([,.;:)])/g, '$1');

/**
 * Two spans written back to back — `$X$$Y$` — mis-nest: the tokenizer pairs the
 * closing delimiter of the first with the opening one of the second. The tell
 * is a span body that still holds a bare `$`; well-formed math never does.
 * This is a regex-only check, so it can run over every string cheaply.
 */
function mayHaveFusedSpans(s) {
  if (!/\${2,}/.test(s)) return false;
  return mathSegments(s).some(({ tex }) => /(?<!\\)\$/.test(tex));
}

/**
 * Pull fused spans apart. Each `$`-run is tried in turn: first by merging the
 * two spans into one (the reading the author almost certainly meant, e.g.
 * `$\mathrm{kg\,m}$$^{-3}$`), then by inserting a separator. A candidate is
 * only kept when it strictly reduces the number of unparseable spans.
 */
/**
 * A `$$` run is a seam — the end of one span jammed against the start of the
 * next — when real content presses against it on both sides. A genuine display
 * delimiter has whitespace or a string edge on at least one side.
 */
function isSeam(s, idx) {
  const before = s[idx - 1];
  const after = s[idx + 2];
  return !!before && !!after && !/[\s$]/.test(before) && !/[\s$]/.test(after);
}

/** Close every seam in one pass — the generator usually dropped them all. */
function mergeAllSeams(s) {
  let out = '';
  let i = 0;
  for (const m of s.matchAll(/\${2,}/g)) {
    if (m[0].length !== 2 || !isSeam(s, m.index)) continue;
    out += s.slice(i, m.index);
    i = m.index + 2;
  }
  return out + s.slice(i);
}

export function separateFusedSpans(s) {
  if (!s.includes('$') || !mayHaveFusedSpans(s)) return s;
  let best = s;
  let bestFail = countMathFailures(s);
  if (bestFail === 0) return s;

  const all = mergeAllSeams(s);
  if (all !== s && mathSegments(all).length > 0 && countMathFailures(all) < bestFail) {
    best = all;
    bestFail = countMathFailures(all);
  }

  // Then close what is left one seam at a time; greedy, but each step has to
  // pay for itself in fewer unparseable spans.
  for (let round = 0; round < 24 && bestFail > 0; round++) {
    const runs = [...best.matchAll(/\${2,}/g)].map((m) => [m.index, m[0].length]);
    let improved = false;
    for (const [idx, len] of runs) {
      const candidates = [];
      if (len === 2 && isSeam(best, idx)) candidates.push(best.slice(0, idx) + best.slice(idx + 2));
      for (let k = 1; k < len; k++) {
        candidates.push(`${best.slice(0, idx + k)} ${best.slice(idx + k)}`);
      }
      for (const cand of candidates) {
        // Deleting the math is not a way to stop it failing.
        if (mathSegments(cand).length === 0) continue;
        const f = countMathFailures(cand);
        if (f < bestFail) {
          best = cand;
          bestFail = f;
          improved = true;
          break;
        }
      }
      if (improved) break;
    }
    if (!improved) break;
  }
  return best;
}

// A relation makes a span a statement in its own right, so two of them side by
// side are two steps of a derivation — `$ab(b-a)+c^2(a-b)=0$$$(b-a)(ab-c^2)=0$$`
// — and welding them would run one line of working into the next.
const RELATION =
  /(?<!\\)[=<>]|\\(?:leq|geq|neq|le|ge|ne|approx|equiv|sim|cong|propto|to|rightarrow|Rightarrow|implies)(?![A-Za-z])/;
// A span that stops mid-expression: it ends on an operator or on a `\text{…}`
// clause — `$$u_i=\dfrac{x_i-25}{10},\ \text{ then }$$`.
const OPEN_END =
  /(?:[=+\-*/<>,(]|\\(?:times|cdot|div|pm|mp|to|rightarrow|Rightarrow|leq|geq|neq|le|ge|ne|approx|equiv)|\\text\s*\{[^{}]*\})\s*$/;
// A span that starts mid-expression: a binary operator or a closing bracket. An
// opening `(` is deliberately not here — a fresh equation begins with one just
// as often as a continuation does.
const OPEN_START =
  /^\s*(?:[=*/<>,)]|[+\-](?!\s*$)|\\(?:times|cdot|div|pm|mp|leq|geq|neq|le|ge|ne|approx|equiv)(?![A-Za-z]))/;

/**
 * One expression torn across a block boundary — `$\overline{X}$$$+\frac{n+1}{2}$$`
 * as a multiple-choice option, where the reader gets `X̄` on one line and a
 * centred `+ (n+1)/2` on the next. Both halves parse, so nothing downstream
 * objects; only the mismatched delimiters give it away.
 *
 * Welds the pair back together when the seam is visibly mid-expression, and
 * shows the result the way the *first* half was written: the span that opened
 * the expression is the one that knows whether it belongs in the line or on one
 * of its own.
 */
// `\begin{matrix}` and the `steel` of `Y_{steel}` are labels, not sentences.
// The prose test reads any lower-case word as one, so strip the environment
// names and the script groups first or every matrix declines to be repaired.
const stripLabels = (body) =>
  body.replace(/\\(?:begin|end)\s*\{[^{}]*\}/g, '').replace(/[_^]\s*\{[^{}]*\}/g, '');

export function mergeAdjacentSpans(s) {
  if (!s.includes('$$')) return s;
  const toks = [...tokenize(normalizeText(s))];
  // The splice below moves text by index, so the rebuild has to be lossless.
  if (toks.map((t) => t.raw).join('') !== s) return s;
  let out = '';
  for (let i = 0; i < toks.length; i++) {
    const a = toks[i];
    const b = toks[i + 1];
    const left = a.kind === 'math' ? String(a.value).trim() : '';
    const right = b && b.kind === 'math' ? String(b.value).trim() : '';
    if (
      left &&
      right &&
      a.display !== b.display &&
      !proseSpan(stripLabels(left)) &&
      !proseSpan(stripLabels(right)) &&
      (OPEN_END.test(left) || (OPEN_START.test(right) && !RELATION.test(left)))
    ) {
      const joined = `${left} ${right}`;
      if (mathOk(joined, a.display)) {
        const d = a.display ? '$$' : '$';
        out += `${d}${joined}${d}`;
        i += 1;
        continue;
      }
    }
    out += a.raw;
  }
  return out;
}

/**
 * An escaped `\$` butted against a delimiter is invisible to the scanner, which
 * then pairs the wrong dollars. A space after it settles the question.
 */
export function normalizeDollarSign(s) {
  if (!s.includes('\\$')) return s;
  const before = countMathFailures(s);
  if (before === 0) return s;
  const cand = s.replace(/\\\$(?=\$)/g, () => '\\$ ');
  return countMathFailures(cand) < before ? cand : s;
}

/**
 * `$100^$th` — the closing delimiter landed before the superscript's argument,
 * so the exponent has nothing to raise. Pull the argument back inside.
 */
export function absorbDanglingScript(s) {
  if (!/[\^_]\$/.test(s)) return s;
  return s.replace(/([\^_])\$([A-Za-z0-9]{1,4})\b/g, (whole, op, arg) => `${op}{${arg}}$`);
}

/**
 * A display span that swallowed a fenced code block. The generator emitted the
 * whole answer inside `$$...$$`, so close the math at the fence and let the
 * code be code. Literal `\n` two-character sequences become real newlines.
 */
export function splitCodeFenceOutOfMath(s) {
  if (!s.includes('```') || !s.includes('$$')) return s;
  return s.replace(/\$\$([\s\S]*?)\$\$/g, (whole, body) => {
    const at = body.indexOf('```');
    if (at === -1) return whole;
    const head = body.slice(0, at).replace(/\\n/g, '\n').trim();
    const tail = body.slice(at).replace(/\\n/g, '\n');
    if (!head || !mathOk(head, true)) return whole;
    return `$$\n${head}\n$$\n\n${tail}`;
  });
}

/**
 * Full string pipeline. Order matters: rebuild before deleting.
 *
 * Three candidates of decreasing ambition are tried in turn, and the first one
 * that does not increase the number of unparseable math spans wins. Some source
 * strings are corrupt beyond repair; on those, restoring a backslash can expose
 * garbage that was previously hidden inside a mangled token. The ladder means a
 * repair can only ever leave a string the same or better, never worse.
 */
export function repairStringDetailed(s) {
  // A bare URL or media path is not prose and holds no maths. It only ever
  // shares punctuation with an equation, so keep every rule away from it.
  if (URL_ONLY.test(s)) return { text: s, tier: 'none' };
  let t = decodeLiteralEscapes(s);
  t = decodeLiteralNewlines(t);
  t = protectNCommands(t);
  t = decodeEntities(t);
  t = repairAnsi(t);
  // After repairAnsi, so the markers it still recognises become `$` rather than
  // being deleted; what reaches here has already lost that context.
  t = stripShortcodeMarkers(t);
  t = repairEscapedCommands(t);
  t = undoubleCommands(t);
  t = repairLostInProse(t);
  t = normalizeAliases(t);
  t = repairChem(t);
  t = repairDelimiters(t);
  t = repairCommands(t);
  // Before every wrapper: an expression that will not parse is one they all
  // decline, so this has to come first or the repair below it never happens.
  // The two torn-block repairs go with it, for the same reason.
  t = closeTornDisplay(t);
  t = closeTornGroups(t);
  t = mendTornText(t);
  t = unnestTextCommands(t);
  t = stripControl(t);
  t = dropReplacementChar(t);
  t = normalizeEscapedDollars(t);
  t = dropNestedDollars(t);
  t = splitCodeFenceOutOfMath(t);
  t = normalizeDollarSign(t);
  t = dropEmptySpans(t);
  t = absorbDanglingScript(t);
  t = separateFusedSpans(t);
  // After separateFusedSpans, which pulls apart the pairs that never rendered;
  // what is left is the pair that renders as two blocks and should be one.
  t = mergeAdjacentSpans(t);
  // Both leave a run the wrappers below can take, so they come before them and
  // after the passes that decide where one span ends and the next begins.
  t = dropOrphanFences(t);
  t = normalizeTextScripts(t);
  t = dropLayoutCommands(t);
  t = dropMulticolumn(t);
  t = absorbLeadingCommand(t);
  t = wrapBareArrays(t);
  t = wrapBareEnvironments(t);
  const conservative = t; // everything except speculative `$`-wrapping
  // The wrapping passes can themselves double a delimiter: a shortcode marker
  // that became a lone `$` leaves the command after it looking bare, so it gets
  // its own pair and the reader ends up with `$ $\boxed{…}$`. Sweep again.
  // wrapBareMathRuns runs last and only sees what the stricter scanner above
  // declined, so it never has to second-guess a span that already exists.
  // dropEmptySpans comes between the two wrappers as well as after them: while a
  // `$ $` is still sitting there the delimiters do not pair, and a run scanner
  // reading unbalanced spans mistakes the inside of a `\boxed{}` for prose.
  // The run scanner goes first and the single-command wrapper mops up after it:
  // run the cheap one first and `e^{0}\cdot\sin 0 = 1` loses its `e^{0}` to a
  // span that starts at the `\cdot`, and the scanner can no longer reach past
  // the delimiter to put it back. dropEmptySpans sits ahead of the scanner
  // because unbalanced spans make the inside of a `\boxed{}` look like prose,
  // and after both because the wrapper can leave a lone `$` doubled.
  // wrapBareFences goes last of the wrappers: it puts a bracket pair the others
  // could only take a piece of back around the whole expression. absorbLeadingCommand
  // runs a second time for the same reason — `+\hat r_{12}` has no span for it
  // to grow until a wrapper has opened one.
  const full = dropEmptySpans(
    absorbLeadingCommand(
      wrapBareFences(
        wrapBareCommands(
          wrapBareMathRuns(dropEmptySpans(absorbScriptTail(repairAsciiScripts(wrapBareExpressions(t))))),
        ),
      ),
    ),
  );

  // dropStrayDollar last, and only on strings the passes above already moved: a
  // spare delimiter is nearly always one of ours — a marker that lost its
  // partner, or an inline span promoted to display over a `$` the source had
  // already written. The odd `$` in an untouched string is as likely to be the
  // author's own, and this pass cannot tell which.
  // dropOrphanSpacing runs on every string: it only ever rewrites what the
  // tokenizer already hands the reader as text, so there is no span for it to
  // disturb. dropStrayDollar is held back to strings the passes above moved —
  // a spare delimiter is nearly always one of ours, and the odd `$` in an
  // untouched string is as likely to be the author's own.
  const finish = (x) =>
    x === s ? dropOrphanSpacing(repairMath(x)) : dropStrayDollar(dropOrphanSpacing(tidy(repairMath(x))));

  const a = finish(full);
  if (a === s) return { text: s, tier: 'none' };

  const baseline = countMathFailures(s);
  if (countMathFailures(a) <= baseline) return { text: a, tier: 'full' };

  if (conservative !== full) {
    const b = finish(conservative);
    if (countMathFailures(b) <= baseline) return { text: b, tier: 'conservative' };
  }

  // Last resort: drop terminal noise only, leaving the math untouched.
  const c = repairMath(stripControl(repairAnsi(s)));
  if (c !== s && countMathFailures(c) <= baseline) return { text: c, tier: 'minimal' };

  return { text: s, tier: 'rejected' };
}

export function repairString(s) {
  return repairStringDetailed(s).text;
}
